(window.STORIES=window.STORIES||[]).push(...[{"n": 166, "l": "الجزء 140 | احداث السنه السابعه من الهجرة | زواج رسول الله من صفيه بنت حيي", "u": "https://www.facebook.com/groups/710210019782034/permalink/836507260485642/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#زواج_رسول_الله_من_صفية_بنت_حُيي\nاتكلمنا  المرة إللي فاتت عن فتح آخر حصون خيبر وتقسيم الغنائم، وقلنا إن صفية بنت حُيي بن أخطب كانت من نصيب  دِحية الكلبي، ولكن واحد من الصحابة جاء لرسول الله ﷺ وقال له إن صفية دي زوجة زعيم اليهود وابنة زعيمهم يعني سيدة بني النّضير وسيدة بني قريظة،\nفمينفعش تكون إلا عند رسول الله ﷺ فوافق رسول الله ﷺ وأخذها لنفسه،\nوده كان من حكمته ﷺ؛ لأن كان ممكن يدخل في نفوس الصحابة شيء أو يحصل بينهم خِلاف، يعني اشمعنى واحد زيهم أخذ حاجة مميزة وهم لأ،\nوخصوصا إن صفية بنت حيي كانت امرأة شريفة عاقلة ذات حسب وجمال، ففعلا مينفعش تكون عند أي حد\nفرسول الله ﷺ أراد إنه يقطع وسوسة الشيطان من البداية، ومتنسوش إن الصحابة بشر برده\nهم أه أطهر الناس قلوبا بعد الأنبياء لكنهم مش معصومين\nفأخذها رسول الله ﷺ لنفسه وكده بقت ملك يمين لرسول الله ﷺ، \nفلما دخلت صفية على رسول الله ﷺ قال لها:\n\"لم يَزل أبوكِ من أشد يهود لي عداوة حتى قتله الله\"\nيعني أبوكِ فضِل طول عمره معاديني وبيعمل المؤامرات ضدي لحد آخر لحظة في حياته،\nوقعد يقولها عن إللي أبوها عمله معاه عشان يوضح لها هو ليه قتله في النهاية،\nفقالت له حفصة:\n\"يا رسول الله!\nإن الله يقول في كتابه: ولا تَزر وازِرة وزر أخرى\"\nيعني أنا حاجة وأبويا حاجة، أنا مليش دعوة باللي أبويا كان بيعمله،انا معملتش حاجة،\nفي البداية كانت صفية بتكره رسول الله ﷺ جدا لأنه قتل أبوها وزوجها وأخوها، فلما رسول الله ﷺ قعد يوضح لها موقفه ويسترضيها ويعتذر لها لحد ما رضيت ومبقاش في قلبها أي شيء من الكره لرسول الله ﷺ،\nوهي نفسها قالت: \n\"كان رسول الله ﷺ من أبغض الناس إليَّ، قَتل زوجي وأبي وأخي فما زال يعتذر إليَّ ويقول : \n《إن أباك ألَّب علي العرب وفعل وفعل》 حتى ذهب ذلك من نفسي\"\nفهنا رسول الله ﷺ خيّرها وقال لها:\nاختاري، فلو اخترتِ الإسلام أمسكتك لنفسي، يعني هتزوجك،\nوإن اخترتِ اليهودية فعسى أن أعتقك فتلحقي بقومك\nيعني رسول الله ﷺ عرض عليها الإسلام وقال لها إنها لو أسلمت هيعتقها ويتزوجها، ولو عايزة تفضل على اليهودية براحتها وهيتركها ترجع لقومها،\nفوافقت صفية رضي الله عنها على الدخول في الإسلام وقالت لرسول الله ﷺ:\nيا رسول الله!\nُلقد هَوَيْتُ الإسلام وصدّقتُ بك قبل أن تدعوني، حيث صرت إلى ذلك وما لي في اليهودية أَرَب، ومالي فيها والد ولا أخ  وخيّرتني الكفر والإسلام، فالله ورسوله أحب إلي من العتق وأن أرجع إلى قومي\nيعني هي بتقول إنها أصلا كانت عايزة الإسلام وحبّاه، ومصدقة برسول الله ﷺ من قبل ما رسول الله ﷺ يدعوها،\nوهي معندهاش أي رغبة في اليهودية وملهاش أصلا حد قريب منها ممكن يقف في طريق إسلامها،\nوهي شايفة إن الإسلام واتباع الله ورسوله أحب إليها من العتق والرجوع لقومها،\nفأسلمت وأعتقها رسول الله ﷺ وتزوجها، وكان مهرها عِتقها وكانت ساعتها مكملتش سبعة عشرة سنة،\nوالعِتق معناه التحرير من العبودية،\nوكان من حِكم زواج رسول الله ﷺ من صفية بنت حيي إستمالة قلوب اليهود،\nيعني لما يكون في بينهم وبين زعيم الدولة الإسلامية ونبي آخر الزمان علاقة نسب ومُصاهرة فالعلاقة دي ممكن تُرقق قلوب اليهود وتفتح قلوبهم للإسلام،\nزي زواج رسول الله ﷺ من أم حبيبة رملة بنت أبي سفيان سيد مكة إللي اتكلمنا عنه قبل كده\nرسول الله ﷺ شاف في خد صفية أو في عينها خُضرة، فسألها عن السبب فقالت له إنها بعد ما تزوجت بكم يوم\nمن كِنانة بن أبي الحقيق وكان ابن عمها؛ حلمت إن القمر خرج من يثرب ونزل في حِجرها، فحكت الرؤيا دي لزوجها فلَطَمها، يعني ضربها على وجهها وقال لها:\nتَمَنِّين مَلِكَ يثرب\nيعني انتِ بتتمني إنك تتزوجي محمد ﷺ،\nوكانت صفية حديثة عهد بعرس، يعني لسه متزوجة من كنانة بن أبي الحقيق حديثاً بقالها كم يوم،\nوكنانة ده كان زوجها الثاني، بعد ما كانت متزوجة من سلاّم بن مشكم،\nوبعد الموقف ده على طول كان جاء جيش رسول الله ﷺ لفتح خيبر،\nوالرؤيا إللي شافتها دي كانت من أسباب إسلامها السريع رضي الله عنها.\n☆خلونا بقى نقف هنا ونفهم كم نقطة كده\n◇أولا:\nالإسلام لم يُشَرّع ابتداء سَبْيِ النساء،\nيعني مش الإسلام هو إللي اخترع موضوع سبي النساء ده،\nسبي النساء كان نظام معمول بيه من قبل الإسلام في جزيرة العرب وحتى في الأمم السابقة،\nوسبي النساء كان له مصادر كثيرة، لكن الإسلام حصرها في مصدر واحد فقط وهو القتال المشروع مع الكفار،\nوسبي النساء الكافرات ممكن يكون سبب في دخولهن للإسلام، ويبقى نجت نفسها من النار،\nورسول الله ﷺ يقول:\n\"عَجِبَ اللَّهُ مِنْ قَوْمٍ يَدْخُلُونَ الْجَنَّةَ فِي السَّلَاسِلِ\"\nيعني في البداية كانوا مُكرهين على الأسر، ومُقيّدين، وبعدين لما عرفوا صِحة الإسلام دخلوا فيه برغبتهم وبعدين كان جزاءهم الجنة،\nفكان أسرهم وتقييدهم في البداية سبب لدخولهم الجنة في الآخرة.\n◇ثانيا:\nانتم عارفين إن العبيد والإماء يُبَاعوا ويُشتروا يعني هم عبارة عن أموال، حلو كده\nلما رسول الله ﷺ يقول لصفية إنه هَيَعْتقها ده معناه إنه هيعطيها مال، والمال ده هو ثمن نفسها لو اتباعت لأنها من السّبي، فبقى مهرها هو ثمن حريتها،\nيعني بدل ما يُعطيها مهرها كأموال، أعطاها حريتها إللي هي أصلا في حد ذاتها تُشترى بالمال، فده يبقى معنى مهرها عِتقُها، وضحت كده\n◇ثالثا:\nفي شريعة الإسلام:\nالمرأة التي تُسْبى وهي كافرة، يعني تبقى أمة بعد الحرب، إذا كانت أُسرت مع زوجها، فلا يَنفسِخ عقدهما،\nيعني يفضلوا زوج وزوجة، وعليه فلا يستطيع مالك المرأة إنه يجامعها؛ لأنها متزوجة،\nولو كانت المرأة بدون زوج، فلا يجوز لمالكها إنه يعاشرها معاشرة الأزواج حتى يَسْتبرِئ رحمها،\nيعني لو كانت حامل، يستنى لحد ما تضع الحمل، ولو مكنتش حامل يستنى لحد ما تحيض حيضة واحدة، \nومجرد ما بقت ملك لواحد من المسلمين مينفعش واحد تاني يعاشرها؛ لأنها مش مَشاع الكل يستمتع بيه،\nطبعا بعكس قبل الإسلام، العبيد والإماء مكنش لهم أي حقوق إطلاقا وكانت الأَمة مشاع بين مالكها وغيره من الرجال،\nفشريعة الإسلام حفظت للمرأة عرضها حتى وهي أمة، \nده غير إن الإسلام فتح أبواب كثيرة لعتق الرقاب ومنها النساء المَسبِيات دول،\nزي مثلا كفّارة اليمين والظّهار والقتل الخطأ وغيرها\nده غير كمان الأحاديث إللي بتشجع على عتق الرقاب بصفة عامة.\nالخلاصة بقى إن الإسلام جاء عشان يحفظ للعبيد والإماء حقوقهم، وكمان عشان يسد كل مسالك الرّق،\nوشريعة الإسلام مليانة بالنصوص إللي بتدعو لعتق العبيد والإماء، \nومفيش في الإسلام نص واحد من قرآن ولا سنة بيأمر أو بيشجع على الاسْترقاق بعكس كتب اليهود والنصارى إللي مليانة كلام عن استحسان الرق والعبودية حتى بصوره الظالمة\nطبعا أنا بقول الكلام ده عشان لما تسمعوا حد بيتّهم الإسلام إنه أباح الرق والعبودية وإن ده فيه اعتداء على حرية الإنسان وحقوقه والكلام ده، ميبقاش عندكم شك إن الكلام إللي بيتقال ده غلط وميدخلش في قلوبكم أي شبهة\n☆وبما إننا بنتكلم عن الشُّبَه ، ففي شبهة بتتقال عن رسول الله ﷺ ، وهي إنه دخل على صفية بنت حيي قبل انتهاء عدتها،\nوطبعا الكلام ده غلط؛ لأن الأصل زي ما قلنا إن المرأة المَسبية تستنى لحد ما تَسْتبرأ رحمها،\nوهو ده إللي حصل مع صفية بنت حيي بن أخطب\nرسول الله ﷺ استناها لحد ما عدتها خلصت قبل ما يدخل عليها؛ لأنها كانت متزوجة،\nوعدّتها كانت إنها تحيض حيضة واحدة، وكانت صفية تقضي عدتها عند أم سليم وهم راجعين للمدينة، \nفلما بَرِأت صفية من الحيض جهّزتها أم سُليم زي ما بنجهز العروس كده وأدخلتها على رسول الله ﷺ،\nوتزوجها رسول الله ﷺ وعمل لها وليمة العرس وكانت الوليمة من الحَيْس، ودي أكلة بتتعمل من خليط التمر والسمن والدقيق.\nوالصحابة كانوا بيتساءلوا بينهم، يا ترى رسول الله هيتزوجها ولّا هيخليها مِلك يمين،\nفقالوا لو حجبها يبقى هيتزوجها، ولو محجبهاش تبقى ملك يمين،\nواحنا اتكلمنا بالتفصيل قبل كده عن الفرق بين الأَمة والحرة في الحجاب\nفباختصار كده:\nرسول الله ﷺ لم يدخل على صفية إلا وهي مسلمة ونفسها راضية ومكنتش كارهاه،\nواحنا شوفناها هي نفسها من شوية قالت إن رسول الله ﷺ استرضاها لحد مبقاش في نفسها حاجة،\nمش زي ما في ناس كذابة بيقولوا إن محمد اغتصب صفية والعياذ بالله، وانها مسكينة مكنش لها أي اختيار تاني،\nوإزاي واحدة ترضى تعاشر رجل قتل أبوها وأخوها وزوجها، وكلام كده استغفر الله العظيم يعني\nوهم لو كانوا كلفوا نفسهم وقرأوا كلام صفية رضي الله عنها نفسها مكنوش قالوا الكلام ده، \nبس هم عايزين يطعنوا في رسول الله ﷺ وخلاص، وبيحتجوا بالطعن ده بأحاديث لا تصح عن رسول الله ﷺ أصلا \nزي  الحديث إللي بيقول إن رسول الله ﷺ أو بلال بن رباح خلّى صفية هي وبنت عم لها يمشوا وسط قتلى أهلها من اليهود عشان يغظيهم\nالحديث ده منكر ولا يصح عن رسول الله ﷺ أصلا\nفالناس دي مش بيدوّروا على حق، ده عايزين يشوّهوا صورة رسول الله ﷺ بأي طريقة وخلاص،\nوطبعا لما يشوّهوا صورة النبي يبقى سهل بعد كده إنهم يطعنوا في القرآن، زي ما كان كفار قريش بيعملوا مع رسول الله ﷺ،\nكانوا بيطعنوا فيه ويقولوا كذاب عشان محدش يسمع لكلامه أصلا،\nيعني هو في حد هيسمع لواحد كذاب، وكذلك لما الناس دي تقول عن رسول الله ﷺ إن اغتصب صفية، مين هيسمع ولّا يتبع دين واحد يغتصب النساء\nبس على مين\nويمكرون ويمكر الله والله خير الماكرين\nالناس دي مش قادرة تفهم إن ده دين ربنا وهو متكفل بحفظه، ومن حفظ الدين حفظ سنة رسول الله ﷺ، فمهما شوهوا ومهما طعنوا على رسول الله ﷺ ربنا بيسَخّر لرسول الله ﷺ إللي يدافع عنه\nوبكده يبقى انتهت غزوة خيبر وخضعت كل تجمعات اليهود في شمال المدينة للمسلمين،\nقريش كان وصل لها الخبر إن رسول الله ﷺ خرج لقتال اليهود في خيبر،\nوهم عارفين قوة حصون خيبر لدرجة إنهم بيعتبروا حصون خيبر من أقوى حصون الحزيرة العربية،\nوبيعتبروا اليهود من اشد الناس قتالا وأقواهم في السلاح،\nفكانوا متوقعين إن رسول الله ﷺ هيتهزم في خيبر ومتخيلوش أبدا إن رسول الله ﷺ ممكن يغلب اليهود،\nفكانوا كل ما ييجي حد من خارج مكة يسألوه عن أمر رسول الله ﷺ ونتيجة الحرب كانت إيه،\nوصل لمكة واحد من الصحابة أسلم في وقت فتح خيبر ولسه محدش يعرف بإسلامه من أهل مكة، وكان اسمه:\nالحَجّاج بن عِلاَط،\nقصته إيه بقى \nالحجّاج ده كان صاحب غارات في الجاهلية، يعني كان بيُغير على القبائل كعادة العرب،\nفلما كان في غارة من غاراته حد قال له إن رسول الله ﷺ في خيبر وإنه جاء ليفتحها،\nفاتجه الحجّاج لرسول الله ﷺ في خيبر وأسلم وحضر مع رسول الله غزوة خيبر،\nوبعد الغزوة قال الحجاج لرسول الله ﷺ إن له عند زوجته في مكة وله عند تجار قريش أموال كثيرة، ولو عرفوا إنه أسلم مش هيرجعوا له أمواله،\nفقال لرسول الله ﷺ:\n\"يا رسول الله!\nائذن لي حتى أذهب فآخذ مالي عند امرأتي، فإنها إن علمت بإسلامي لم آخذ منه شيئًا\"\n فأَذِن له رسول الله ﷺ، فقال الحجاج :\n لاَبُدَّ لي يا رسول الله مِنْ أن أقول، فأذن له رسول الله ﷺ أن يقول ما شاء\"\nيعني الحجاج بيطلب الإذن من رسول الله ﷺ إنه يروح ياخد أمواله إللي في مكة، فرسول الله ﷺ أَذِن له،\nلكن المشكلة زي ما قلنا إنهم لو عرفوا بإسلامه هيمنعوا عنه أمواله، فطلب من رسول الله ﷺ الإذن في إنه يكذب عشان ياخد أمواله من قريش،\n☆ملحوظة:\nيجوز الكذب إذا كان هو السبيل الوحيد للإنسان عشان  يحفظ دمه وماله وعرضه.\nفهنا رسول الله ﷺ أَذِن للحَجّاج بالكذب عشان يأخذ ماله إللي أهل مكة هيأخذوه ظلما وعُدوانا لو عرفوا إنه أسلم\nالمهم، \nالحَجّاج وصل مكة وشاف أهل مكة وهم بيسألوا الناس الجايين من خارج مكة عن نتيجة المعركة بين خيبر ورسول الله ﷺ،\nفسألوا الحجاج وقالوا: \nالخبر يا حجاج\nيعني عندك معلومات عن إللي حصل بين محمد ﷺ ويهود خيبر،\n فقال لهم: \nعندي ما يَسُرُّكم\nلم يِلْقَ محمد وأصحابه قومًا يُحسنون القتالَ غيْر أهل خَيَابِر، قد هُزم هزيمة لم يُسمع بمثلها قط وأُسِرَ محمدٌ أسرًا، فقالوا لَنْ نَقْتُلَه حتى نبعث به إلى أهل مكّة\nيعني بيقولهم أنا عندي أخبار هتفرحكم، محمد ﷺ وأصحابه مقابلوش حد بيعرف يقاتل غير أهل خيبر، \nيعني كل المعارك إللي كان كسبها قبل كده عشان إللي واجههم كانوا ضعفاء،\nلكن أهل خيبر هم أهل القتال بقى، فلما قاتلهم غلبوه وأسروه هو وأصحابه، وقالوا إنهم مش هيقتلوه هيرسلوه لأهل مكة يتصرفوا معاه،\nفلكم بقى أن تتخيلوا فرحة قريش لما سمعت الكلام ده\nقعدوا يصيحوا من شدة الفرح، وقالوا:\nقد جاءَكم الخبر\nيعني أيوة كده هو ده الكلام\nفقال لهم الحجاج:\n\"أعينوني على جَمْعِ ما لي على غُرَمَائي فإنّي أريد أن أقدم فأصيبَ من غنائم محمد وأصحابه قبل أن يسبقني التجّار إلى ما هناك\"\nيعني بيقولهم مقابل الأخبار السعيدة إللي قلتها لكم دي اجمعوا لي أموالي إللي عند التجار، عشان أنا عايز أرجع لخيبر واشتري من غنائم محمد وأصحابه قبل ما حد من التجار يسبقني هناك ويشتري إللي انا عايزه،\nفقاموا وجمعوا له أمواله بسرعة مكنش يتخيلها، وراح لمراته وكان عندها الأموال بتاعته فقال لها: \n\"مالي، لعلّي ألْحَقُ بخيبر فأُصيبَ من البيع قبل أن يسبقني التجّار\"\nيعني هاتي أموالي إللي عندِك عشان أروح خيبر واشتري من الغنائم قبل ما التجار يسبقوني،\nمين بقى اللي سمع الكلام ده\nالعباس بن عبد المطلب عم رسول الله ﷺ، فطبعا اتصدم من الكلام إللي سمعه عن رسول الله ﷺ لدرجه انه مبقاش قادر يقوم\n فنادى على غلام له، عبد يعني فقال له:\n\"اذهب إلى الحجّاج فقُلْ يقول لك العبّاس الله أعلى وأجلّ من أن يكون الذي تُخْبُره حقًّا\"\nيعني بيقول له روح للحجاج وقول له إن الكلام اللي انت بتقوله ده ربنا لن يسمح أبدا إنه يحصل لرسوله\nفجاء الغلام للحجّاج وأخبره بكلام العباس، فقال الحجاج للغلام:\n\"قل لأبي الفضل أخْلِني في بعض بيوتك حتى آتِيَك ظُهْرًا ببعض ما تحبّ واكتم عني\"\nأبو الفضل هي كنية العباس، ومعنى الكلام إنه بيقول خلينا نتقابل الظهر في السر وهقولك أخبار تفرحك بس متقولش لحد على أي حاجة،\nفأتاه ظهرًا فناشده الله ليكتمنّ عليه ثلاثة أيّام فواثقه العبّاس على ذلك،\nيعني لما اتقابلوا الظهر حلّفه الحجاج إنه ميجبش سيرة لحد عن الكلام إللي هيقوله له لمدة ثلاثة أيام بس، فوافق العباس على طلبه،\nفحكى الحجاج للعباس إن رسول الله ﷺ انتصر على اليهود وفتح حصونهم وتزوج بنت ملكهم، وهو عمل الحيلة دي عشان يسترجع أمواله،\nففرح العباس بانتصار رسول الله ﷺ على اليهود، وخرج الحَجّاج في الليل من مكة واتجه للمدينة،\nوبعد ما مرت الثلاثة أيام، العباس خرج من بيته وعدّي على تجمعات قريش وكانوا بيتكلموا عن الأخبار إللي الحَجاج قالها لهم،\nفقال لهم العبّاس الحقيقة وإن رسول الله ﷺ فتح خيبر وتزوج بنت ملكهم وإن الحجّاج هرب بماله إللي استرجعه منهم ومن زوجته،\nفسألوه: مين إللي قالك الكلام ده\nفقال لهم إن الحجاج نفسه هو إللي قال له، وإنه أصلا كان مسلم وهو عمل الحيلة دي عشان يسترجع أمواله،\nفاتصدموا صدمة جامدة وركبهم الهم والغم، لأنهم متخيلوش أبدا إن قوة المسلمين وصلت لدرجة إنهم يفتحوا خيبر إللي قلنا إنهم بيعتبروها أقوى حصون الجزيرة العربية على الإطلاق،\nوفرح المسلمون إللي كانوا كاتمين إسلامهم في مكة ومش قادرين يهاجروا بفتح خيبر،\nويادوب عدّى خمس أيام ووصلت الأخبار لمكة تأكد لهم المعلومات عن فتح خيبر\nإن شاء الله المرة الجاية هنشوف خطة رسول الله ﷺ بعد خيبر هتكون إيه"}, {"n": 167, "l": "الجزء 141 | احداث السنه السابعه من الهجرة | إسلام ابو هريرة | غزوة ذات الرقاع", "u": "https://www.facebook.com/groups/710210019782034/permalink/836508293818872/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#إسلام_أبو_هريرة\n#غزوة_ذات_الرّقاع\nاتكلمنا الأجزاء الأخيرة إللي فاتت عن فتح خيبر وعن مَجِيء الصحابة إللي كانوا هاجروا للحبشة وانضمامهم لرسول الله ﷺ في منطقة خيبر، \nواتكلمنا عن بعض الأفراد إللي أسلموا وجاءوا واشتركوا مع رسول الله ﷺ في فتح خيبر،\nمن الناس إللي أسلمت دي واحد من قبيلة دَوْس اسمه عبد شمس بن صَخر،\nوقبيلة دَوس دي لو تفتكروا زعيمها الطُّفيل بن عمرو الدوسي إللي كفار مكة قعدوا يحذروه من رسول الله ﷺ في بداية الدعوة إلى الإسلام لحد ما وضع القطن في ودنه وبعدين أسلم ورجع لقومه يدعوهم للإسلام\nاتكلمنا عنه بالتفصيل في الجزء السابع والعشرين\nالمهم،\nكان من الناس إللي أسلمت على يد الطّفيل بن عمرو الدوسي عبد شمس بن صخر، وهو كان له أسماء كثيرة جدا قبل إسلامه أشهرها عبد شمس،\nلما جاء للمدينة مهاجر لقى رسول الله ﷺ خرج لقتال اليهود في خيبر، فتوجه هو كمان لخيبر وحضر فتح خيبر،\nوسمّاه رسول الله ﷺ 《عبد الرحمن》 بدل عبد شمس وبقى اسمه 《عبد الرحمن بن صخر》،\nوكان عنده هِرة أو قطة صغيرة بيرعاها وبيحطها في كمه، فكُنّيَ بها، يعني بقى اسمه أبو هريرة واشتهر بالكنية دي،\nوبقى مُلازِم لرسول الله ﷺ على طول، بيروح معاه في كل مكان،يعني لا بيشتغل ولا وراه أي حاجة غير رسول الله ﷺ، فكانت النتيجة إنه بقى أكثر الصحابة حفظا لحديث رسول الله ﷺ، \n مع إنه أسلم متأخر لكن من ساعة ما أسلم لم يفارق رسول الله ﷺ عشان كده روى أحاديث عن رسول الله ﷺ كثير من الصحابة مكنوش يعرفوها،\nلأن المهاجرين كانوا مشغولين بالتجارة، والأنصار مشغولين بزراعة الحقول بتاعتهم،\nلكن عبد الرحمن بن صخر تفرّغ لرسول الله ﷺ ومكنش عنده شغل، وبالتالي كان من الفقراء ومكنش بيلاقي أكل يأكله، وهو من أهل 《الصُّفَّة》،\n☆والصُّفَّة أو الظُّلَّة مكان في آخر المسجد النبوي أمر به رسول الله ﷺ إنه يُظَلّل بجِرِيد النخل، وأُطلق عليه اسم \"الصُّفَّة\" أو \"الظُّلَّة\"،\nورسول الله ﷺ جهز المكان ده عشان يكون مأوى للغرباء أو العُزاب من المهاجرين والوافدين إللي ملهمش مأوى ومكان يسكنوا فيه، والناس دي بقى اسمهم أهل الصُّفة،\nوكان رسول الله ﷺ كثيراً ما يجالسهم، ويأنس بهم، ويناديهم إلى طعامه، ويُشرِكهم في شرابه،\nيعني رسول الله ﷺ كان بيقعد معاهم كثير ويتكلم معاهم، وبيشاركهم في الأكل والشراب، ولو حد أرسل له هدية أو صدقات بيشاركهم فيها،\nوساعات أعدادهم تكون قليلة وساعات تكون كبيرة.\nفكانوا فقراء وكان أبو هريرة منهم ومن شدة فقر أبو هريرة\nكان ساعات بيسأل الصحابة عن بعض آيات القرآن وهو عارفها أملاً منه إن الصحابي يعرض عليه الأكل،\nيعني يقوله طيب تعال نتغدى وبعدين أقولك على الآية،\nحتى حصلت قصة ظريفة بين رسول الله ﷺ وبين أبو هريرة بمناسبة سؤال أبو هريرة للصحابة\nبيحكي القصة دي أبو هريرة نفسه بيقول إنه كان بيبقى جعان جدا لدرجة إن بيربط الحجر على بطنه من شدة الجوع،\nوكان بيقعد للصحابة على طريقهم إللي بيمشوا فيه،\nفعدّى عليه أبو بكر الصديق رضي الله عنه فسأله عن آية من القرآن، وكان الهدف من سؤاله إن يعرض عليه الأكل،\nفأبو بكر رضي الله عنه منتبهش للي كان عايزه أبو هريرة رضي الله عنه\nفجاوبه أبو بكر عن الآية إللي كان بيسأل عنها ومشي،\nفمر عليه عمر بن الخطاب فسأله أبو هريرة عن آية من القرآن وهو عارفها بس كان عايزه يأكله،\nفعمر برده منتبهش للي كان عايزه أبو هريرة فأخبره بالآية إللي سأل عنها ومشي،\nفمر عليه أبو القاسم ﷺ \nأول ما رسول الله ﷺ شاف أبو هريرة عرف إللي في نفسه وشاف الجوع في وجهه فتبسم ﷺ لأبي هريرة وقال له:\n\"يا أبا هِر الْحَق\"\nيعني تعال ورايا يا أبا هريرة، فمشي رسول الله ﷺ ومشي وراه أبو هريرة،\nفدخل رسول الله ﷺ لبيت من بيوته فلقى فيه قَدح فيه لبن، يعني طبق أو كوباية فيها لبن، فسأل رسول الله ﷺ \nمن أين هذا اللبن؟\nيعني مين إللي جاب اللبن ده، فقالوا: \nأهداه لك فلان أو فلانة، يعني حد بعته لرسول الله ﷺ كهدية، فقال رسول الله ﷺ لأبي هريرة:\nأبا هر! الْحَق إلى أهل الصفة فادعهم لي\nيعني روح نادي لأهل الصفة، وكان ساعتها عددهم أكثر من خمسين،\nفلما سمع أبو هريرة رسول الله ﷺ بيقول له نادي أهل الصفة، زعل وقال في نفسه وهو اللبن ده هيعمل إيه في أهل الصفة ولّا هيكفي مين ولّا مين،\nأنا بس كنت عايز أشرب منه شربة أتقوّى بها بدل مانا مش قادر أقف،\nفراح أبو هريرة ونادى لأهل الصفة فجاءوا، فأمره رسول الله ﷺ إنه يسقيهم اللبن،\nفتخيلوا إحساس أبو هريرة وهو شايف اللبن إللي نفسه في شربة منه غيره هو إللي بيشربه وطبعا من وجهة نظره مش هيتبقى له حاجة في النهاية\nوبالرغم من إنه مش عايز يعمل كده ونفسه ياخد اللبن ويشربه لوحده لكنه قال كلمة محتاجين كلنا نتعلمها، قال:\n 《ولم يكن من طاعةِ الله وطاعة رسوله ﷺ بُد》\nيعني مهما كان أنا مش عايز أعمل حاجة معينة أو شايف إنها ممكن يكون فيها ضرر عليّ أو مش في مصلحتي فلااازم أطيع الله ورسوله، مفيش مفر من الطاعة دي حتى لو كانت عكس هوايا،\nوالكلام ده في أكل وشرب مش حرام وحلال، وواحد وصل بيه الجوع لمرحلة إنه بيربط حجر على بطنه، ومع ذلك قدّم أمر رسول الله ﷺ على نفسه\nاحنا بقى وضعنا إيه، هل ده شعارنا احنا كمان؟\nلما بنلاقي أمر من الله أو من رسوله ﷺ بنقدم الأوامر دي على هوانا ورغباتنا ولّا بنعمل العكس وبندور على ألف حِجة وحِجة عشان نبرر عدم طاعتنا لأوامرهم؟\nأظن محتاجين وقفة مع نفسنا\nالمهم، \nأبو هريرة قعد يسقيهم واحد واحد، وكل واحد منهم يشرب لحد ما يرتوي ويشبع واللبن في القَدَح زي ماهو\nبعد مانتهى منهم كلهم أعطى القَدح لرسول الله ﷺ واللبن فيه لم ينقص منه شيء\nفوضعه رسول الله ﷺ على يديه ونظر إلى أبي هريرة وتبسم وقال له: أبا هر!\nفرد عليه أبو هريرة وقال له:\n لبيك يا رسول الله!\nقال له رسول الله ﷺ:\n بقيت أنا وأنت\nيعني مش فاضل غيري أنا وانت مشربناش،\n فقال أبو هريرة: صدقت يا رسول الله!\nفقال له رسول الله ﷺ :\nاقعد فاشرب\nفقعد أبو هريرة وشرب، وكل ما ينزل القدح من على فَمِه رسول الله ﷺ يقول له اشرب وقعد رسول الله ﷺ يقول لأبو هريرة..اشرب...اشرب...اشرب، لحد ما أبو هريرة نفسه قال:\n لا والذي بعثك بالحق، ما أجدُ له مَسْلَكًا\nيعني خلاص بطني اتملت ومبقاش فيها أي مكان للشرب،\nفأخذ رسول الله ﷺ من أبو هريرة القدَح وحمد الله وسمّى وشرب الباقي من اللبن.\n☆شوفتم إن طاعة الله ورسوله مش بييجي من وراها إلا الخير إزاي \nتخيلوا كده لو أبو هريرة كان اعترض على رسول الله ﷺ ومسمعش الكلام وقال لرسول الله ﷺ إنه عايز يشرب هو لأنه جعان ومش هيقدر يستحمل،\nآخره كان هيشرب شوية من اللبن وخلاص زي ماهو حتى قال،\nهو مش قال إنه كان عايز شربة يتقوى بيها،\nأهه لأنه قدم طاعة الله ورسوله مش بس أخذ شربة واحدة، ده قعد يشرب من اللبن لحد ما شبع\nنفس الموقف ده بيحصل في حياتنا، كتير أوي بنستعجل رغباتنا حتى ولو بمعصية الله،\nمع إننا لو صبرنا وأطعنا الله ورسوله مش بس هناخد إللي احنا عايزينه، ده احنا هناخد إللي احنا عايزينه وزيادة،\nفاحنا لو عايزين حاجة من ربنا يبقى لازم نطيعه عشان ناخدها، ورسول الله ﷺ نفسه قال:\nإن ما عند الله يُنال بطاعته ولا يُنال بمعصيته\nوده إللي أبو هريرة عمله، قال إيه، قال:\n《 ولم يكن من طاعةِ الله وطاعة رسوله ﷺ بُد》\n◇طبعا في حاجات ربنا بيمعنها عننا لحكمة هو يعلمها حتى لو كنا طائعين، بس ده مش موضوعنا أنا بتكلم كقاعدة عامة\nدي من بعض مواقف أبو هريرة مع رسول الله ﷺ، وأبو هريرة له مواقف كثيرة ورَوَى أحاديث كثيرة جدا عن رسول الله ﷺ، إن شاء الله هنتكلم عن بعض المواقف دي في النص واحنا بنحكي عن مواقف رسول الله ﷺ مع الصحابة\nكده غزوة خيبر خلصت، ويبقى رسول الله ﷺ قضى على تهديد اليهود للدولة الإسلامية، وقريش دلوقتي في معاهدة مع المسلمين، يعني بقت على الحياد ومفيش منها أي تهديد،\nوبالتالي بدأ المسلمون من جميع أنحاء الجزيرة العربية يتوجهوا للمدينة،\nوبدأت الناس إللي كانوا خايفين من الدخول في الإسلام بسبب قريش يتوجهوا للمدينة عشان يسلموا، وبدأت أثار صلح الحديبية تظهر، \nوبكده رسول الله ﷺ بدأ يتفرغ للقبائل التانية إللي بتهدد دولة الإسلام، \nمن أكبر القبائل إللي كانت بتُؤذي المسلمين قبيلة غَطَفان إللي كان سيدهم عُيَيْنة بن حِصن الأحمق المطاع، فاكرينهم\nإللي حاصروا المدينة في غزوة الأحزاب، وإللي خرجوا عشان يساعدوا يهود خيبر في حربهم ضد رسول الله ﷺ،\nده غير طبعا حادثة بئر معونة وحادثة ماء الرجيع، فمصائبهم مع المسلمين كثيرة فلازم لهم وقفة\nفأخرج رسول الله ﷺ سرية لقبائل نجد إللي فيها غطفان بقيادة الصحابي 《أَبان بن سعيد بن العاص》\nفاكرين أبان\nالرجل المشرك إللي كان أجار عثمان بن عفان لما دخل مكة في صلح الحديبية عشان يبلغ رسالة رسول الله ﷺ لقريش، وكان قابل راهب في الشام وسأله عن رسول الله ﷺ فالراهب أكد له إن محمد ﷺ فعلا نبي، والإسلام دخل في قلبه ساعتها، اتكلمنا عنه في الجزء مائة وعشرة\nأهه أبان ده إخواته الاتنين كانوا أسلموا من زمان وهاجروا للحبشة، وكل شوية كانوا يرسلوا له رسالة بيدعوه فيها للإسلام وهو رافض الإسلام،\nلحد ما جاءت غزوة خيبر ورجع آخر وفد من الحبشة بقيادة جعفر بن أبي طالب ورجع معاه إخوة أبان فلما رجعوا وهم في الطريق أرسلوا لأخوهم مرة تانية يدعوه للإسلام فأسلم أبان بن سعيد وهاجر للمدينة واستعمله رسول الله ﷺ قائد لسرية لتأديب قبائل غطفان، واتعرفت السرية باسم سرية أبان بن العاص، \nطبعا توقيت السّرِية كان امتى بالضبط محدش يعرف، في إللي بيقول في شهر صفر، وفي إللي بيقول في شهر ربيع الأول، المهم إن أبان أسلم ورسول الله ﷺ استعمله في سرية لقتال قبائل غطفان،\nومش بس سرية أبان، ده رسول الله ﷺ أرسل لقبائل غطفان حوالي ست سرايا متفرقين لقتالهم،\nومش بس كده ده رسول الله ﷺ خرج لهم بنفسه في غزوة،\nلكن جيش رسول الله ﷺ في الغزوة دي كان جيش يعتبر عدده صغير نسبيا،\nلأن جيش المسلمين في الوقت ده كان متوزع في أماكن متفرقة، شوية في خيبر وشوية في المدينة وشوية في فَدَك وشوية في وادي القُرى،\nلأن الأماكن دي تعتبر أماكن غير مستقرة، ولسه مفتوحة فعشان ميحصلش إنهم يخلفوا العهد مع رسول الله ﷺ، \nفكان لازم يكون في حَامِية أو جيوش صغيرة تحافظ على استقرار الأماكن إللي رسول الله ﷺ فتحها،\nفالجيش إللي خرج مع رسول الله ﷺ كان حوالي أربعمائة من الصحابة،\nومكنش معاهم غير عدد قليل من البَعير يركبوه، وكان الستة  من الصحابة بيتعاقبُوا على البعير الواحد، \nيعني واحد يركب شوية وينزل وغيره يركب وهكذا،\nومشي الجيش بالطريقة دي مسافة طويلة جدا مسافة عدة ليال لحد ما توَغّلوا في قبائل غطفان،\nوالمشي الكثير ده أثر عليهم رضي الله عنهم، يقول واحد من الصحابة اسمه أبو موسى الأشعري بيوصف حاله وحال أصحابه:\n\"خَرَجْنَا مَعَ النَّبِيِّ فِي غَزْوَةٍ، وَنَحْنُ سِتَّةُ نَفَرٍ، بَيْنَنَا بَعِيرٌ نَعْتَقِبُهُ، فَنَقِبَتْ أَقْدَامُنَا وَنَقِبَتْ قَدَمَايَ وَسَقَطَتْ أَظْفَارِي،\nوَكُنَّا نَلُفُّ عَلَى أَرْجُلِنَا الْخِرَقَ؛ فَسُمِّيَتْ غَزْوَةَ ذَاتِ الرِّقَاعِ لِمَا كُنَّا نَعْصِبُ مِنَ الْخِرَقِ عَلَى أَرْجُلِنَا\"\nيعني بيقول إن بسبب مشيهم الكتير وقلة ركوبهم؛ أقدامهم اتجرحت جراح شديدة وسقطت أظافر أبو موسى رضي الله عنه، وكانوا بيلفّوا القماش المقطّع على أقدامهم،\nفاتسمت الغزوة دي بغزوة ذات الرِّقاع، عشان كانوا بيضعوا الرقاع أو قطع القماش على أرجلهم، رضي الله عنهم.\nوالله يا جماعة الدين ده موصلناش بسهولة، وصلنا بدماء الصحابة وتضحياتهم\nمين يستحمل يمشي في صحراء في عز الحر على رجله لدرجة إن رجله تتقطع وأظافره تسقط عشان يدافع عن دينه ويحافظ عليه؟\nوبعدين بعد كل التضحيات دي، الناس أول حاجة تفرط فيها هي الدين\nعارفين الأعجب من ده كله إيه\nأبو موسى الأشعري بعد ما حكي إللي حصل معاهم ده ندم إنه قاله وقال:\n\"ما كنت أصنع بأن أذكره\"\nيعني أنا إيه إللي خلاني أقول، استفدت أنا إيه دلوقتي لما حكيت الكلام ده،\nأبو موسى رضي الله عنه كان عايز يخلي العمل ده بينه وبين ربنا ومحدش يعرفه، لأنهم كانوا حريصين جدا على الإخلاص، والحمد لله إنه حكى الموقف ده عشان نعرف تضحيات الصحابة كانت عاملة إزاي، ونعرف الفرق بيننا وبينهم\nوصل رسول الله ﷺ والصحابة معاه لقبائل غطفان، والمُتوقع إن يبقى في حرب طاحنة بين الطرفين، وخصوصا بعد الأذى إللي المسلمين اتعرضوا له على إيدهم أكثر من مرة،\nلكن قبائل غطفان الشرسة إللي عددها أكبر من جيش المسلمين بكتير جدا وإللي عارفين الطرق بتاعتهم أكثر من المسلمين إللي جايين من بعيد وتعبانين من السفر هربوا من المسلمين ومرضوش يحاربوهم\nوصدق رسول الله ﷺ:\n\" نُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ\"\nيعني رسول الله ﷺ يكون بينه وبين عدوه مسافة شهر وأعدائه مرعوبين منه\nوطبعا قبائل غطفان اتصدموا من نفسهم ومن ردة فعلهم أمام المسلمين،\nيعني هم أصلا قبائل مُرتزقة عايشين على السلب والنهب وقطع الطريق ومش بيخافوا من حد، \nييجي مجموعة صغيرة زي دول يخلوهم يعيشوا في رعب وكمان يهربوا منهم\nفبدأوا ينظروا للإسلام والمسلمين بنظرة مختلفة، أيوة هم مأخدوش قرار الدخول في الإسلام لكن على الأقل نظرتهم للإسلام اختلفت ودخل في قلوبهم جلال وهيبة الإسلام،\nفلو حتى مدخلوش الإسلام فعلى الأقل مش هيقدروا يتعرضوا للمسلمين بأذى في المدينة\nرسول الله ﷺ لقى قبائل غطفان هربت، فقعد في مكان المعركة كم يوم كعادته عشان يثبت للجميع إنه مش خايف وإن الطرف الثاني هو إللي هرب منه،\nتجهز رسول الله ﷺ مع الجيش عشان يرجعوا للمدينة، وهم راجعين....حصل إيه\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 168, "l": "الجزء 142 | احداث السنه السابعه من الهجرة | مواقف بعد غزوة ذات الرقاع", "u": "https://www.facebook.com/groups/710210019782034/permalink/836509837152051/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#مواقف_بعد_غزوة_ذات_الرقاع\nوقفنا المرة إللي فاتت  عند عودة رسول الله ﷺ من غزوة ذات الرّقاع، في طريق العودة حصل ثلاثة مواقف،\n◇الموقف الأول كان مع رسول الله ﷺ،\nخلونا نشوف حصل إيه\nلما كان الجيش راجع للمدينة قعدوا يريحوا، لأن الطريق طويل، ونزل رسول الله ﷺ عند شجرة وعلق عليها سيفه ونام تحتها وباقي الصحابة ناموا كلهم هم كمان،\nفجاء رجل من الأعراب المشركين من بني ثعلبة من قبائل غطفان اسمه غَوْرَث بن الحارث وتسلّل لحد ما وصل للمكان إللي نايم فيه رسول الله ﷺ،\nفأخذ سيف رسول الله ﷺ إللي كان متعلق على الشجرة ورفعه فوق رأس رسول الله ﷺ وهو نايم\nفجأة رسول الله ﷺ صحي من النوم وشاف الأعرابي واقف على رأسه بالسيف،\nفغَوْرَث بن الحارث قال لرسول الله ﷺ:\nأتَخَافُني؟ \nيعني انت خايف مني، والسؤال ده غريب أصلا\nيعني هو ده وقت حوار\nالطبيعي إنه مجرد ما أخذ السيف يقتل رسول الله ﷺ وبكده هياخد شرف كبير عند أهل غطفان لأنه قتل عدوهم وعدو قريش،\nلكن ربنا حافظ لرسول الله ﷺ من إن حد يقتله، قال تعالى:\n\" وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ\"\nفغَوْرَث بن الحارث مقدرش يقتل رسول الله ﷺ لأن ربنا منعه، وفضل مستني رسول الله ﷺ لحد ما صحي وبدأ يتكلم معاه،\nفلما غَوْرَث بن الحارث سأل رسول الله ﷺ إذا كان خايف منه ولّا لأ، قال له رسول الله ﷺ بكل ثبات:\nلا\nيعني رسول الله ﷺ مدخلش في قلبه ذرة خوف ولا اهتز له شعرة، مع إنه أعزل وغَوْرَث فوق رأسه،\nحتى غَوْرَث بن الحارث نفسه تعجب من ثبات رسول الله ﷺ وخصوصا إن مفيش حد معاه يدافع عنه،\nطبعا ده من وجهة نظر غَوْرَث بن الحارث المشرك، لكن ميعرفش إن ربنا يعصم رسول الله ﷺ من أذى الناس، \nفقال لرسول الله ﷺ: \nفمن يمنعك مني\nيعني انت مش خايف وانت لوحدك وأعزل مش معاك حاجة تدافع بيها عن نفسك، طيب انت بقى جايب الثقة دي منين، مين إللي هيمنعك مني وينقذك ،\nفقال ﷺ : الله\nفلما رسول الله ﷺ قال الله، سقط السيف من يد غَوْرَث بن الحارث، فأخذه رسول الله ﷺ وقال لغَوْرَث بن الحارث:\nمن يمنعك مني؟!!\nيعني انت بقى مين هينقذك مني دلوقتي\nغَوْرَث بن الحارث كافر فمش هيقدر يقول الله، ومقدرش  يلجأ إلى آلهته المزعومة من الأصنام\nلكنه طمع في كرم رسول الله ﷺ ،فقال غَوْرَث بن الحارث لرسول الله ﷺ:\nكُنْ خَيْرَ آخذٍ \nيعني خليك انت أحسن مني وعاملني بالحُسنى، فرسول الله ﷺ قال له:\nتشهد أن لا إله إلا الله وأني رسول الله؟\nفقال غَوْرَث بن الحارث:لا، ولكن أُعاهدك ألا أقاتلك، ولا أكون مع قوم يقاتلونك\nيعني هو لم يُسلم، لكنه وعد رسول الله ﷺ إنه مش هيقاتله مرة تانية ولا هيشارك مع حد في أي قتال ضده ﷺ، \nفأطلق رسول الله ﷺ سراحه ولم يعاقبه وعفا عنه،\nفرجع غَوْرَث بن الحارث لقومه وقال لهم:\nجئتُكم من عند خير الناس\nفي رواية بتقول إن عدد كبير من أهله أسلم بسبب الموقف ده، فسواء فعلا كانوا أسلموا أو لأ،\nفالأكيد إن الموقف ده ترك أثر كبير جدا في قبائل غطفان وأثبت لهم إن رسول الله ﷺ فعلا نبي من عند الله، \nليه\nلأن مش من طبع الملوك والقادة ولا عادتهم إنهم يتركوا أو يعفوا عن أي حد هدّدهم بالقتل بالطريقة دي، فمش من عادتهم الرحمة والكرم والتسامح للدرجة دي، لكن ده من طبع الأنبياء،\nفكل الأحداث إللي حصلت دي خلّتهم يفكروا جديا في الإسلام\n◇الموقف الثاني :\nلما كان رسول الله ﷺ مع المسلمين في غزوة ذات الرّقاع، واحد من المسلمين أصاب زوجة رجل من المشركين بجروح وكان زوج المرأة دي غائب،\nفلما رجع المشرك وعرف إللي حصل لزوجته وكان جيش المسلمين خلاص في طريق رجوعه للمدينة، أقسم إنه مش هيسيب جيش المسلمين إلا لما يُصيب أحد أصحاب رسول الله ﷺ بجراح،\nفخرج الرجل يتتبع أثار جيش المسلمين، في الوقت ده كان رسول الله ﷺ والجيش إللي معاه نزلوا في وادي عشان يريحوا فيه، فرسول الله ﷺ قال للصحابة:\n\" مَنْ رَجُلٌ يَكْلَؤُنَا لَيْلَتَنَا هَذِهِ\"\nيعني مين إللي يحرسنا الليلة دي، فتطوع عمار بن ياسر من المهاجرين، و عبّاد بن بِشر من الأنصار،\n☆بالمناسبة\nعبّاد بن بشر رضي الله كان من سادة الأوس ومن أوائل الناس إللي أسلمت على يد مصعب بن عمير لما جاء للمدينة قبل هجرة رسول الله ﷺ، حتى إنه كان أسلم قبل أُسيد بن حُضير وسعد بن معاذ،\nوكان القرآن شغله الشاغل وكان بيردده ليل نهار لدرجة إنه اتعرف بين الصحابة بلقب 《الإمام وصديق القرآن》\nوحضر مع رسول الله ﷺ كل الغزوات، وكان شجاع وشديد القوة وكان متخصص في الحراسة، \nففي غزوة الأحزاب تولى حراسة قُبة أو خيمة رسول الله ﷺ ،وهيتولى الحراسة برده في غزوة تبوك بعدين،\nوالموقف إللي احنا فيه دلوقتي تولى فيه الحراسة\nنام رسول الله ﷺ ومعاه الجيش، وخرج عبّاد وعمار من الوادي عشان يستلموا الحراسة،\nفسأل عمار عبّاد بن بشر إذا كان عايز نوبة الحراسة تكون له الأول ولّا ينام وبعدين يصحى يبدل مع عمار،\nفقال له عباد إنه هيبتدي الحراسة هو الأول، فنام عمار بن ياسر، وقام عباد بن بشر يصلي جنبه،\nفي الوقت ده الرجل المشرك كان وصل لمكان جيش المسلمين فشاف إن في واحد واقف من بعيد فعرف إن ده حارس جيش المسلمين، \nفالمشرك عايز ينفذ قسمه، فراح واخد سهم وحاطه في القوس ورمى بيه عباد بن بشر\nالسهم أصاب عباد لكنه متحركش من مكانه، عبّاد شد السهم من جسمه ورماه وكمّل صلاته\nالمشرك استغرب إن عبّاد لسه واقف، فقال أكيد السهم لم يُصب عباد؛ لأن الطبيعي إللي يتصاب بسهم بيقع ميبقاش واقف كده ولا كأنه جرى له حاجة\nالمشرك أخذ سهم تاني وراح رامي عبّاد بن بشر، والسهم أصاب عباد، وعباد لسه واقف زي ما هو، كل إللي عمله إنه شد السهم من جسمه تاني ورماه وكمل صلاته\nوالرجل المشرك مش قادر يستوعب إللي بيحصل\nفراح واخد سهم ثالث ورمى بيه عباد بن بشر للمرة الثالثة\nوالسهم أصاب عباد، فنزع السهم من جسمه ورماه، وبعدين ركع وسجد وكمل صلاته وسلم وأيقظ عمار بن ياسر إللي كان نايم في الأرض،\nعمار صحي شاف الدم بينزف من عباد رضي الله عنه اتخض طبعا من المنظر وشاف الثلاثة أسهم في الأرض،\nفقال عمار لعباد :\nسبحان الله هلّا أيقظتني عند أول سهم رماك به\nيعني مش كنت تصحيني من أول مرة اتصبت فيها،\nفقال له عباد:\n\"كنت في سورة أقرأها فلم أحب أن أقطعها حتى أفرغَ منها، وايْم الله لولا خوفي أن أُضيعَ ثغراً أمرني رسول الله ﷺ  بحفظه لكان قَطْعُ نَفَسِي أحبّ إلى من قطعها\"\nيعني بيقول لعمار إنه كان بيقرأ سورة من القرآن ومحبش إنه يقطع قراءة السورة إلا لما يخلصها، وكان فعلا ناوي على كده حتى لو كانت النتيجة هي موته،\nلكنه تذكر إن رسول الله ﷺ استأمنه على سلامته وعلى سلامة الجيش إللي معاه، فكان لازم يقدم أمر رسول الله ﷺ على هواه ورغبته الشخصية فكمّل الصلاة وأيقظ عمار،\nطبعا المشرك لما شاف إن عمار كمان صحي هرب وعرف إن جيش المسلمين لو مسكه مش هيسيبه،\nولما واحد بس ينضرب بالسهام ثلاثة مرات ولسه واقف ، أمال باقي الجيش عامل إزاي\nفهو برّ قسمه خلاص وأصاب واحد من المسلمين فمفيش داعي إنه يعرّض نفسه للقتل\nواتعالج عباد بن بشر رضي الله عنه وكمل المسلمون طريقه للعودة للمدينة.\n◇في الطريق حصل الموقف الثالث:\nوالموقف كان عبارة عن حوار بين جابر بن عبد الله بن حرام وبين رسول الله ﷺ، خلونا نشوف إللي حصل\nجابر بن عبد الله كان راكب على جمل ضعيف، وكل شوية جمله يتأخر عن باقي الجيش،\nوالجيش يسبقه، فرسول الله ﷺ كان ماشي وراء الجيش عشان يشوف لو حد من أصحابه محتاج مساعدة أو حد منهم متأخر، فرسول الله ﷺ شاف جابر وهو متأخر عن الجيش وقاعد مهموم وحزين، فقال رسول الله ﷺ لجابر:\nمالك يا جابر؟\nيعني إيه إللي حصل لك، وإيه إللي مأخرك عن الجيش، فقال جابر:\n يا رسول الله! أبطأني جملي هذا\nيعني أنا متأخرتش عن الجيش متعمد، ده الجمل ده هو إللي مأخرني،\nُفقال له رسول الله ﷺ: أَنِخْه\nيعني بيقول له قعّده على الأرض، فلما جابر قعّده على الأرض، رسول الله ﷺ أخذ عصا من خشب ونغَز بها الجمل كم نَزْغة، وبعدها قال لجابر يركب على الجمل،\nفلما ركب جابر على الجمل بقى جمله يسابق ناقة رسول الله ﷺ، وناقة رسول الله ﷺ كانت سريعة مكنش بيسبقها أي جمل تاني،\nفتحول الجمل الضعيف إللي مش قادر يمشي لجمل سريع يسابق ناقة رسول الله ﷺ، وده من معجزاته ﷺ، \nوهنا بدأ حوار لطيف بين رسول الله ﷺ وبين جابر\nرسول الله ﷺ قال لجابر:\nأتبيعني جملك هذا يا جابر ؟ \nيعني إيه رأيك تبيعني الجمل بتاعك ده، فقال له جابر:\nبل أَهَبُه لك\nيعني هديهولك من غير أي ثمن يارسول الله، فرسول الله ﷺ قال لجابر:\nقال: لا، ولكن بعنيه\nيعني هاخده منك بثمنه، فقال جابر: \nفَسُمْنِيه\nيعني تمّنه لي وقول انت سعر مناسب، فرسول الله ﷺ قال له: قد أخذتُه بدرهم\nيعني رسول الله ﷺ بيقوله خلاص هشتريه منك بدرهم\nفجابر اتصدم وقال لرسول الله ﷺ:\n لاااا، إذن تَغْبِنُنِي يا رسول الله\nيعني بيقوله انت كده بتظلمني يا رسول الله، تخيلوا كده إن الدرهم يساوي حوالي ثلاثة جرام من الفضة،\nيعني حوالي مائة وخمسين جنيه مصري، طبعا على حسب سعر الفضة اليومين دول أنا مش متابعة الأسعار أوي\nوثمن الجمل حوالي ثمانية آلاف جنيه،\nفتخيلوا حاجة تمنها ثمانية آلاف تتباع بمائة وخمسين، أكيد طبعا فيها غَبْن وظلم\nفرسول الله ﷺ قال لجابر:\nفَبِدَرْهمين\nيعني خلاص متزعلش نفسك، خليهم درهمين\nفجابر قال لرسول الله ﷺ: لا\n☆ملحوظة:\nمش معنى إن جابر قال 《لا》 لرسول الله ﷺ إنه كده عصى أمره؛ لأن ده مش أمر من رسول الله ﷺ، ده بيعرض عليه عرض يا إما يوافق يا إما يرفض\nالمهم،\nرسول الله ﷺ استمر يرفع في سعر الجمل لحد ما بلغ الأُوقية، والأُوقية في عهد رسول الله ﷺ تساوي حوالي  مائتين جرام فضة يعني عشرة آلاف جنيه،\nفقال جابر لرسول الله ﷺ:\nأفَقد رضيت يا رسول الله؟\nيعني انت موافق على السعر ده، فقال رسول الله ﷺ:\nنعم\nفقال جابر لرسول الله ﷺ: فهو لك\nيعني خلاص بقى بتاعك، لكنه اتفق مع رسول الله ﷺ إنه هيعطيه الجمل لما يرجع للمدينة؛ لأن مفيش حاجة تانبة يركب عليها غير الجمل ده،\nوصل رسول الله ﷺ للمدينة قبل جابر، فلما وصل جابر لرسول الله ﷺ وكان واقف على باب المسجد، \nفرسول الله ﷺ قال لجابر:\nآلْآنَ قَدِمْتَ ؟\nيعني انت لسه جاي دلوقتي، فقال له جابر : نعم، فقال له رسول الله ﷺ: \nفَدَعْ جَمَلَكَ ،فَادْخُلْ فَصَلِّ رَكْعَتَيْنِ \nيعني سيب جملك هنا وادخل صلي ركعتين في المسجد، فدخل جابر وصلى ركعتين، وأمر بلال إنه يوزن أوقية من الفضة ويعطيها لجابر رضي الله عنه ويزده، وأخذ جابر المال وترك الجمل ومشي، \nرسول الله ﷺ قال لبلال :\nادْعُ لِي جَابِرًا \nيعني روح نادي لجابر، فلما نادى عليه بلال جابر رضي الله عنه خاف إن رسول الله ﷺ يرجع في كلامه ويرجّع له الجمل وياخد المال\nفلما وصل جابر لرسول الله ﷺ قال له رسول الله ﷺ:\nخُذْ جَمَلَكَ ، وَلَكَ ثَمَنُهُ\nيعني خد الجمل بتاعك وتمنه كمان هدية لك\n☆موقف رسول الله ﷺ مع جابر من روائع المواقف إللي حصلت بينه ﷺ وبين الصحابة\nرسول الله ﷺ من البداية أصلا مكنش عايز الجمل ولا حاجة، رسول الله ﷺ كان عايز يساعد جابر بمبلغ من المال؛ لأنه كان فقير وكان عنده سبع بنات اخوات، لكن مكنش عايز يحرجه، فاستغل موقف الجمل ده عشان يساعده،\nوكمان مكنش عارف المبلغ المناسب، فبدأ معاه من أول الدرهم لحد ما وصل للمبلغ إللي يرضاه جابر رضي الله عنه،\nوالموقف ده بيُظهر حب رسول الله ﷺ لأصحابه، واهتمامه بهم، والتلطف في الكلام معهم ومساعدتهم في حل مشكلاتهم،\nتخيلوا إحساس جابر رضي الله عنه ناحية رسول الله ﷺ  بعد موقف زي ده، الإنسان بطبيعته أسير الإحسان والقلوب طُبِعَت على حب من أحسن إليها،\nفما بالكم لما ييجي الإحسان من رسول الله ﷺ، تخيلوا كم الحب إللي في قلوب الصحابة ناحية رسول الله ﷺ،\nكان لهم حق فعلا يحبوه أكثر من أي حد في حياتهم ويفدوه بأرواحهم، رسول الله ﷺ كان أغلى حاجة في حياة الصحابة، وده موقف واحد بس من مواقف كثيييرة جدا\n☆ملحوظة للأمانة العلمية\n◇أولا:\nفي اختلاف بين العلماء عن زمن غزوة ذات الرقاع، في علماء قالوا إنها كانت بعد غزوة أُحد بسنة واحدة،\nوعلماء قالوا إنها كانت سبعة هجريا بعد غزوة خيبر زي ما شرحنا كده، وكل فريق له أدلته،\nفأنا أخذت بالرأي إللي بيقول إنها كانت في السنة السابعة للهجرة؛ لأن أبو موسى الأشعري إللي حكينا عنه المرة إللي فاتت كان في الحبشة ومجاش من الحبشة إلا مع فتح خيبر، فإزاي بقى حضر غزوة ذات الرقاع في السنة الرابعة من الهجرة بعد غزوة أحد\n◇ثانيا:\nفي علماء قالوا إن قصة عِقد السيدة عائشة إللي ضاع منها والصحابة قعدوا من غير ماء وبسبب القصة دي نزلت آية التيمم كان في غزوة ذات الرقاع، واحنا قلنا القصة دي حصلت في غزوة بني المصطلق إللي حصل بعدها حادثة الإفك على طول في الجزء مائة واثنان.\n◇ثالثا:\nالعلماء اختلفوا برده في توقيت نزول صلاة الخوف، احنا قلنا إنها كانت في وقت صلح الحديبية، لما حكينا القصة إللي حصلت مع خالد بن الوليد،\nلكن في علماء قالوا إنها نزلت في غزوة ذات الرقاع، وأصلا غزوة ذات الرقاع مختلف في توقيتها هل هي كانت في السنة الرابعة ولّا في السنة السابعة\n♡أنا مش بحب أدخلكم في اللغبطة بتاعة الاختلاف بين العلماء، لكن قلت لكم الاختلاف هنا من باب الأمانة\nفمادام الاختلاف سائغ خلاص ممكن ناخد بالرأي إللي نرتاح له أكثر وخصوصا إن الموضوع كله عن قصص وأخبار مش حلال وحرام،\nوإلا لما يكون في اختلاف في الحلال والحرام والشبهة فاحنا بناخد دايما بالأحوط\nبعد غزوة ذات الرقاع، رسول الله ﷺ استمر في إرسال السرايا لمنطقة قبائل غطفان،\nإن شاء الله المرة الجاية هنعرف إيه السرايا إللي خرجت دي وإيه أهم الأحداث إللي حصلت فيها"}, {"n": 169, "l": "الجزء 143 | احداث السنه السابعه من الهجرة | القرآن وعامل الزمن | اشققت عن قلبه", "u": "https://www.facebook.com/groups/710210019782034/permalink/836511647151870/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#القرآن_وعامل_الزمن\n#أشققت_عن_قلبه\nوقفنا المرة إللي فاتت عند السّرايا إللي رسول الله ﷺ أرسلها بعد رجوعه من غزوة ذات الرقاع، وقلنا هنتكلم عنها المرة دي ونشوف أهم الأحداث إللي حصلت فيها،\nبس قبل ما نتكلم عنها في حد سألني سؤال مهم، وممكن ناس كتير عايزة تعرف إجابته عشان كده أنا هقول لكم السؤال والإجابة بتاعته لأنه يُعتبر من الشُّبه المُنتشرة إللي محتاجة رد\n☆السؤال بيقول: \nاحنا إزاي عرفنا كل الأحداث دي عن حياة رسول الله ﷺ، مش يمكن في حد ألّف في الأحداث أو قال أحاديث رسول الله ﷺ مقلهاش، إزاي وصل لنا الكلام ده كله\nالإجابة:\nعشان نجاوب على السؤال ده لازم نجاوب الأول على هل احنا متأكدين إن القرآن من عند ربنا فعلا ولّا لأ\nطبعا احنا كلنا مؤمنين إن القرآن كلام الله أنزله على رسوله، طيب إيه الدليل، إيه إللي يخلينا متأكدين إن القرآن فعلا من عند ربنا\nطبعا في أدلة كتير، لكن خلونا ناخد دليل منهم،\nعشان نكون متأكدين إن الدين أو الوحي أو القرآن من عند ربنا فعلا لازم القرآن يثبَت أمام 《إختبار الزمن》\nبمعنى إن القرآن موجود من أكثر من ألف وأربعمائة سنة، وكل شوية العلوم بتتطور وبيحصل اكتشافات جديدة،\nوالقرآن فيه أكثر من ألف آية بتتكلم عن العلوم،\nطبعا القرآن مش كتاب علوم لكنه كتاب علامات، يعني مش بيشرح الحقائق العلمية ولكنه بيُشير إليها بإشارات تثبتها الدراسات العلمية مع مرور الوقت،\nولو احنا شوفنا الحقائق العلمية وإللي العلم الحديث اكتشفه\nسواء من خمسين سنة فاتت أو مائة سنة أو مائتين سنة أو حتى أربعمائة سنة؛ هنلاقي إن القرآن ذكرها من ألف وأربعمائة سنة،\n◇يعني مثلا:\nالقرآن يتحدث عن خلق الكون في الآية:\n\"أَوَلَمْ يَرَ الَّذِينَ كَفَرُوا أَنَّ السَّمَاوَاتِ وَالْأَرْضَ كَانَتَا رَتْقًا فَفَتَقْنَاهُمَا.\"\nوهو ده إللي اكتشفه العلم الحديث عن الانفجار العظيم\n◇مثال تاني:\nعرفنا إن الأرض كروية لما قام فرانسيس دريك بجولة حول الأرض، سنة 1956\nوده إللي القرآن ذكره القرآن في سورة النازعات:\n\" والأرضَ بعدَ ذَلِك دَحَاهَا\"\nفالقرآن يُشير إلى بيض النعامة ومعروف إن بيض النعامة يميل للشكل البيضاوي، فالمعنى إن الأرض بيضاوية،\n◇مثال ثالث:\nفي السابق كانت الناس مفكرة إن القمر له ضوء خاص به،\nلكن من مائة سنة أو مائتين سنة فاتت العلماء اكتشفوا بأن ضوء القمر هو ضوء معكوس ومش خاص به، \nوالكلام  مذكور في القرآن من أكثر من ألف وأربعمائة سنة، قال تعالى:\n\"تَبَارَكَ الَّذِي جَعَلَ فِي السَّمَاءِ بُرُوجًا وَجَعَلَ فِيهَا سِرَاجًا وَقَمَرًا مُّنِيرًا \"\n◇مثال رابع:\nالعلماء كانوا بيقولوا إن الشمس ثابتة حول محورها مش بتلف يعني، ولكن القرآن بيقول إن الشمس بتدور حول محورها مش ثابتة،\nوهو ده إللي اكتشفه العلماء حديثا في السنين الآخيرة،\nقال تعالى:\n\"وَهُوَ الَّذِي خَلَقَ اللَّيْلَ وَالنَّهَارَ وَالشَّمْسَ وَالْقَمَرَ كُلٌّ فِي فَلَكٍ يَسْبَحُونَ\"\nيبقى مين إللي يقدر يقولنا كل الحقائق دي في القرآن وإللي معرفنهاش إلا مؤخرا غير خالق الكون\nوقيسوا بقى على كده لما القرآن يتكلم عن علم الأجنة ومراحل خلق الجنين، \nوعلم الأحياء والنبات والمياه وغيرها إللي معرفناش عنها غير في السنين إللي فاتت بعد التقدم العلمي،\nفلو احنا وضعنا اختبار العلوم ده لكل الكتب المقدسة، الكتاب الوحيد إللي هينجح في الاختبار ده ويعدّيه هو القرآن الكريم\nولحد دلوقتي مفيش آية واحدة في القرآن العلم الحديث أثبت إنها باطلة، بالعكس ده بيثبت صحة الآيات ولسه العلم بيتقدم ولسه في بعض الأمور الغامضة إللي العلم لسه معرفهاش،\nوفي أمثلة كتير بس احنا هنا مش بنتكلم عن الإعجاز العلمي للقرآن بالتفصيل، إللي عايز يعرف ممكن يعمل بحث على النت ويعرف\nفكده احنا بقينا مطمئنين وعلى يقين إن القرآن ده من عند الله وكل كلامه صدق\nوعلى الأساس ده خلونا نشوف ربنا قال إيه، قال:\n\"إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ\"\nالذكر إللي هو القرآن، يعني ربنا بيقول إنه حافظ للقرآن من إن أي حد يغيره أو يبدله،\nطيب من آيات القرآن ربنا بيأمر بإقامة الصلاة، وإيتاء الزكاة ، \nممكن حد يقول لنا الصلاة دي شكلها إيه ولّا نصليها إزاي من خلال آيات القرآن \nطبعا مفيش ولا آية بتشرح الصلاة أو بتقول لنا أنصبة الزكاة،\nيبقى معنى الكلام إن في حاجة تانية هي إللي بتشرح القرآن، والحاجة دي هي سنة رسول الله ﷺ وأحاديثه\nيبقى ربنا زي ما هو حافظ للقرآن فهو حافظ لسنة رسول الله ﷺ وأحاديثه.\n◇طيب إيه الطريقة إللي ربنا بيحفظ بيها سنة رسول الله ﷺ  من التحريف والتغيير\nاحنا ديننا ده واخدينه بالتَّلقِّي، يعني رسول الله ﷺ تلقّى العلم من جبريل عن طريق الوحي، وبعدين رسول الله ﷺ كان بيُلقّن الصحابة وبيعلمهم مباشرة تعاليم الإسلام،\nزي ما قال لهم صلوا كما رأيتموني أصلي، وزي ما كان بيقعد يحكي لهم عن الأمم السابقة، وزي ما كان بيخطب فيهم ويشرح لهم ويجاوب على أسئلتهم،\nفالصحابة أخدوا العلم من رسول الله ﷺ وبدأوا ينقلوا العلم ده للجيل إللي جاء بعدهم وإللي مشفش رسول الله ﷺ والجيل ده اسمه جيل التابعين،\nوالتابعين دول جاء بعدهم جيل مشفش الصحابة والجيل ده بقى ياخد العلم بالتلقي برده من التابعين وبقى اسمهم تابعي التابعين،\nوهكذا بقى كل جيل يسلّم العلم للجيل إللي بعده، طبعا جاء ناس وضّاعين بيكذبوا على رسول الله ﷺ وبيقولوا أحاديث رسول الله ﷺ مقلهاش،\nفربنا سخّر العلماء عشان ينقّوا أحاديث رسول الله ﷺ ويبينوا منها الصحيح من الضعيف من الموضوع وبقى في علماء متخصصين في علم الحديث وعلم الجَرْح والتعديل،\nطبعا تنقية أحاديث رسول الله ﷺ أخذت وقت ومجهود كبير جدا،\nلدرجة إن واحد زي الإمام البخاري لما كان بيبحث عن الناس إللي معاهم أحاديث رسول الله ﷺ كان بيسأل عن الناس دي وعن حياتهم كويس جدا ولو لقى إن واحد فيهم كذب ولو كذبة واحدة في حياته مكنش بياخد منه الحديث\nوفي قصة عنه إنه عرف إن في واحد معاه حديث لرسول الله ﷺ، فلما راح للرجل ده شافه بينادي للحمار بتاعه عن طريق إنه ماسك الجلابية بتاعته كأن فيها أكل عشان الحمار ييجي وياكل وطلع الرجل بيخدع الحمار وكان بيكذب عليه ومكنش معاه أكل  ولا حاجة،\nفلما الإمام البخاري شاف إللي الرجل ده عمله مرضاش ياخد منه الحديث\nوطبعا في قصص كتير جدا للإمام البخاري عن رحلته في تجميع أحاديث رسول الله ﷺ بس أنا قلت لكم مثال واحد للتوضيح،\nفكتاب البخاري يعتبر  أصح كتاب بعد القرآن الكريم.\nفخلاصة الكلام إن ربنا حافظ لسنة رسول الله ﷺ زي ماهو حافظ للقرآن،\nوكمان ربنا بيقول في القرآن :\n\"وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا\"\nفتخيلوا كده لو السنة مش صحيحة فإزاي هنسمع كلام رسول الله ﷺ في إللي هو قاله\nورسول الله ﷺ نفسه قال:\n\" ألا إني أُوتيتُ القرآنَ ومثله معه\"\nيعني التشريعات مش بس في القرآن ده في السنة كمان، واحنا اتكلمنا عن قصة تحريم الحُمر الأهلية وشوفنا إن تحريمها مش موجود في القرآن،\nومش بس كده، ده زي ما في إعجاز في القرآن ففي إعجاز في الحديث النبوي،\nيعني مثلا في حديث رسول الله ﷺ:\n\"إِذَا أَوَى أَحَدُكُمْ إِلَى فِرَاشِهِ فَلْيَنْفُضْ فِرَاشَهُ بِدَاخِلَةِ إِزَارِه، فَإِنَّهُ لَا يَدْرِي مَا خَلَفَهُ عَلَيْهِ\"\nوالعلماء في العصر الحديث أثبتوا إن الإنسان لما بينام على فراشه تموت في جسمه خلايا فتسقط على الفراش، ولما  يستيقظ تبقى الخلايا موجودة على فراشه، \nولما ينام مرة أخرى تسقط الخلايا مرة ثانية؛ فتتأكسد هذه الخلايا وتدخل إلى جسم الإنسان وتسبب له أمراض،\nوحاول الغربيون غسل الفراش بالمنظفات لكن بدون فائدة فواحد من العلماء نَفَض الفِراش ثلاث مرات فلقى إن الخلايا اختفت\nطبعا في فوائد تانية لنفض الفراش، لكن أنا هنا بركز على نقطة الإعجاز العلمي\nفالقرآن والسنة وجهان لعملة واحدة، مفيش واحد فيهم يستقيم من غير التاني،\nفلازم نفهم الكلام ده كويس لأن حاليا في ناس كتير بتطعن في السنة وفي أحاديث رسول الله ﷺ وبيقولوا احنا هناخد بالقرآن فقط، بحجة احنا مش متأكدين إذا كان الكلام ده الرسول فعلا قاله ولّا لأ\nواحنا اتكلمنا عن النقطة دي بالذات واحنا بنتكلم عن تحريم الحمر الأهلية في فتح خيبر لو تفتكروا \nفأنا كده أثبت لكم إن ربنا بيحفظ السنة زي ما هو بيحفظ القرآن، وبالتالي كل المعلومات إللي وصلت لنا عن رسول الله ﷺ صحيحة إذا كانت عن طريق الأحاديث الصحيحة\nنرجع بقى لموضوع السرايا إللي أرسلها رسول الله ﷺ بعد غزوة ذات الرقاع، السرايا دي كانت برده لديار قبائل غطفان،\nوكانت سرايا تأديب وترهيب في نفس الوقت،\nعشان ميتجرأوش ويهجموا على المسلمين في المدينة تاني، لأنهم كانوا كل شوية يستغلوا انشغال المسلمين بالقتال مع قريش ومع اليهود وغيرهم ويقوموا هاجمين على أطراف المدينة،\nفلما كل شوية يلاقوا إن رسول الله ﷺ بيرسل لهم سرايا فكأنه بيقول لهم احنا فاضيين لكم ومش هنسمح لكم بالهجوم على المدينة تاني\nطبعا السرايا دي مخرجتش كلها في وقت واحد هي خرجت على مدار السنة،\nوأول سرية أخرجها رسول الله ﷺ كانت مكونة من مائة وخمسين أو مائتين رجل من الصحابة رضي الله عنهم،\nكان قائدهم الصحابي غالب بن عبدالله الليثي، واتسمت السرية باسمه،\nالسرية كانت موجهة إلى بعض قبائل غطفان، يقال إنهم  بني عوال، وبني عبد بن ثعلبة، ويُقال إلى الحُرَقَة من جهينة،\nالمهم،\nلما الجيش قرب من المكان إللي هم رايحينه وقفوا وأرسلوا عشرة رجال يستطلعوا الأخبار، ويرجعوا يخبروا غالب وباقي الصحابة،\nفلما رجعوا وأخبروه، بدأ يجهز للهجوم واستنى لحد وقت الفجر وهجمت السرية على الأعراب، \nفي البداية حصل عندهم ارتباك لكنهم رتبوا صفوفهم وبدأوا يقاتلوا المسلمين،\nفبدأ الأعراب ينهزموا وواحد منهم هرب، فجري وراه أسامة بن زيد بن حارثة ومعاه واحد من الأنصار، فلحقوه،\nفرفعوا السيف عشان يقتلوا فالأعرابي إللي كان لسه بيقاتل المسلمين وحريص على قتلهم قال:\nأشهد أن لا إله إلا الله وأن محمداً رسول الله،\nفالأنصاري نزّل سيفه، لكن أسامة قتل الرجل، فالأنصاري قال له إنت إزاي تقتله بعد ما قال لا إله إلا الله \nفأسامة قال له: هو قالها لأنه كان خايف من القتل\nيعني هو قال كده عشان ينجي نفسه من الموت، بيضحك علينا يعني، وهو كان لسه حالا بيقاتلنا، فواضح جدا إنه قال لا إله إلا الله عشان منقتلوش،\nفالأنصاري سكت، وخلاص السرية رجعت للمدينة، وراحوا لرسول الله ﷺ عشان يقولوا له الأخبار،\nالأنصاري إللي كان مع أسامة حكى لرسول الله ﷺ إللي حصل وإن أسامة قتل رجل بعد ما قال لا إله إلا الله، \nفجاء أسامة لرسول الله ﷺ، فسأله رسول الله ﷺ عن إللي حصل فحكى له القصة، فرد عليه رسول الله ﷺ وقال له:\n\" يَا أُسامةُ! أَقَتَلْتَهُ بَعْدَمَا قَالَ: لا إِلهَ إِلَّا اللَّهُ\"\nيعني انت قتلته بعد ما قال لا إله إلا الله \nفأسامة رد على رسول الله ﷺ وقال:\n\" يَا رسولَ اللَّهِ! إِنَّمَا قَالَهَا خَوْفًا مِنَ السِّلاحِ\"\nيعني هو قال كده عشان كان خايف من السيف والقتل، فهو عارف إنه لما يقول لا إله إلا الله محدش هيقدر يقتله،\nفرد عليه رسول الله ﷺ رد قاطع، احنا نفسنا محتاجينه في حياتنا قال:\n《 أَفَلا شَقَقْتَ عَنْ قَلْبِهِ حَتَّى تَعْلَمَ أَقَالَهَا أَمْ لا؟!》\nيعني انت كنت فتحت قلبه وعرفت إذا كان قالها عشان خايف من الموت ولّا لأ،\nمش يمكن ربنا ألقى في قلبه الإيمان في اللحظة دي، انت إزاي عرفت نيته ولّا هو بيفكر في إيه،\nوقعد رسول الله ﷺ يقول لأسامة ويكرر:\nفَكيْفَ تَصْنَعُ بلا إِله إِلَّا اللَّهُ إِذا جاءَت يوْمَ القيامَةِ؟!\nفَكيْفَ تَصْنَعُ بلا إِله إِلَّا اللَّهُ إِذا جاءَت يوْمَ القيامَةِ؟!\nفقال أسامة: \n\"فَما زَالَ يُكَرِّرُهَا عَلَيَّ حَتَّى تَمَنَّيْتُ أَنِّي لَمْ أَكُنْ أَسْلَمْتُ قَبْلَ ذلِكَ الْيَوْمِ\"\nيعني رسول الله ﷺ قعد يكرر عليه الكلام عشان يأنبه ويعرّفه أد إيه إللي عمله ده كان غلط شديد جدا، \nوإن الإنسان مجرد ما قال لا إله إلا الله محمد رسول الله يبقى دمه معصوم ولا يجوز قتله،\nفتألم أسامة وتمنى إن الغلط إللي عمله ده كان قبل إسلامه، لأن الإسلام بيمسح أي حاجة كانت قبله زي ما التوبة تمسح إللي كان قبلها\nوهنا رسول الله ﷺ لم يعاقب أسامة ولا قتله بقتل نفس ولا أخذ منه الدّية لأنه كان مُتَأَوّل،\nيعني أسامة مكنش متعمد إن يقتل واحد من المسلمين لكنه شاف من الظاهر إن الرجل ده كافر وعشان يهرب من القتل قال لا إله إلا الله، ومكنش صادق في إسلامه.\n☆وهنا بقى احنا محتاجين وقفة مهمة جدا\nتخيلوا احنا بنقع في نفس إللي وقع فيه أسامة كم مرة في اليوم \nطبعا مش بتكلم عن القتل\nأنا بتكلم إننا بنحكم على نيات الناس وتصرفاتهم مع إنهم هم نفسهم بيقولوا عكس إللي احنا بنتهمهم بيه\nيعني مثلا حصل إن بنت ربنا قدر لها إن يتقدم لها عريس وتتخطب وتتزوج في عشر أيام تقريبا أو أسبوعين،\nفلما جت تعزم أصحابها على الفرح أصحابها زعلوا كانوا مفكرين إنها كانت مخطوبة من زمان ومخبية عليهم مع إنها أكدت لهم وحلفت إن الموضوع فعلا تم في عشر أيام،\nوهم فضلوا مكذبينها،\nطيب يا جماعة انتم شققتم عن قلبها وعرفتم إذا كانت فعلا صادقة ولّا كاذبة، وقيسوا بقى على كده، هتلاقوا مواقف كتير بتحصل معانا بنبقى فعلا محتاجين نقول لنفسنا: \n《أَفَلا شَقَقْتَ عَنْ قَلْبِهِ》\nطبعا الموقف إللي حكيته ده من أرض الواقع عن حد أعرفه شخصيا، فمش ببالغ ولا حاجة يعني\nفاحنا يا جماعة ملناش غير الظاهر، إللي هيُظهر لنا الخير هنعامله بالخير،\nوإللي يظهر الشر يُعامل بالشر ويُتهم بالشر، \nشوفوا عمر بن الخطاب رضي الله عنه بيقول إيه للناس بعد ما تولى خلافة المسلمين:\n\" كان الناسُ يُؤخذون بالوحي على عهد النبي ﷺ، وإن الوحي قد انقطع - أي: بموت النبي ﷺ، \nوإنما نأخذكم الآن بما ظَهر لنا من أعمالكم،\nفمَن أظهر خيرًا قرَّبناه، وأمِنَّاه، وليس لنا من سريرته شيءٌ، الله الذي يُحاسبه على سريرته، ومَن أظهر شرًّا لم نُقربه، ولم نَأمَنْه\"\nيعني بيقول إن في عهد رسول الله ﷺ لو حد أخفى حاجة كان الوحي بيفضحه، وبنعرف هو مخبي إيه، \nلكن بعد انقطاع الوحي خلاص مبقناش نعرف الناس مخبية إيه؛ فملناش غير الظاهر، إللي هنشوفه بيعمل الخير وظاهره الخير هنقرّبه ونستأمنه، وسريرته إلى الله يحاسبه عليها يوم القيامة،\nوإللي هيعمل الشر ويُظهر الشر هنبعده ومش هنستأمنه على حاجة\nفالمطلوب مننا إننا نعامل الناس باللي يَظهر منهم ولا نتهم نياتهم مهما كانت الظروف حواليهم إيه\nإن شاء الله المرة الجاية هنكمل الكلام عن باقي السرايا"}, {"n": 170, "l": "الجزء 144 | احداث السنه السابعه من الهجرة | إنما الدنيا لأربعة نفر", "u": "https://www.facebook.com/groups/710210019782034/permalink/836522650484103/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#إنما_الدنيا_لأربعة_نَفَر\nاتكلمنا المرة إللي فاتت عن أول سَرِيّة أخرجها رسول الله ﷺ بعد غزوة ذات الرقاع وكانت سرية غالب بن عبد الله الليثي،\nالسرية التانية أخرجها رسول الله ﷺ بقيادة عمر بن الخطاب رضي الله عنه لمنطقة تُرَبَة في شهر شعبان ومعاه ثلاثين رجل من الصحابة ولما وصل هناك هرب المشركين في منطقة تُرَبَة من عمر رضي الله عنه،\nورجع لرسول الله ﷺ في المدينة وأخبره باللي حصل معاه،\nفي نفس الشهر شهر شعبان أخرج رسول الله ﷺ سرية تانية بقيادة بَشير بن سعد أبو النُّعمان بن بشير ، والنعمان كان أول مولود يُولد للأنصار بعد الهجرة زي ما قلنا قبل كده\nالمهم،\nبشير بن سعد خرج في جيش مكون من ثلاثين رجل من الصحابة، واتوجهوا إلى بني مُرّة ناحية فَدك، وفدك دي إللي كان فيها يهود وعملوا صُلح مع رسول الله ﷺ،\nوصلت السرية إلى بني مُرة، فبشير ملقاش غير رعاة الماشية، فسألهم عن أهل القرية قالوا له : في بَوَادِيهم\nيعني في أرضهم إللي بيزرعوا فيها، يعني زي ما بنقول في وقتنا دلوقتني : في أشغالهم،\nفبشير بن سعد أخذ الماشية إللي كانت موجودة كغنيمة وتوجه راجعا للمدينة،\nفي الوقت ده كان شاف المسلمين رجل، فراح الرجل ده للناس من بني مرة وصرخ فيهم وقال لهم إن المسلمين أخذوا ماشيتهم غنائم،\nفتجمع عدد كبير من بني مُرة وخرجوا في أثر المسلمين لحد ما لحقوهم ووصلوا عندهم في الليل، فباتوا الليلة دي يترامون بالنبل، يعني كل فريق يرمي بالسهام على التاني لحد ما خلصت سهام المسلمين،\nفلما جاء الصباح هجم المشركين على المسلمين وحصل بينهم قتال فقُتل معظم إللي كانوا مع بشير وقاتل بشير قتال شديد جدا لحد ما جسمه اتملى بالجراح ووقع على الأرض، وضربه واحد المشركين على كعبه فلم يتحرك بشير،\nفقالوا ده كده خلاص مات، فأخذ المشركون الماشية بتاعتهم ورجعوا لقريتهم،\nأما بشير فمكنش مات كان لسه عايش، وفضل بين القتلى لحد الليل، فلما جاء الليل تحامل على نفسه وتوجه ناحية فدَك ونزل عند واحد من اليهود إللي كانوا عاملين معاهدة صلح مع رسول الله ﷺ،\nفاليهودي عالج جروح بشير واستضافه عنده لحد ما اتحسن بعد كم يوم، ورجع بشير لرسول الله ﷺ في المدينة وأخبره باللي حصل معاه\nشوفنا بعد انتصار رسول الله ﷺ في خيبر وخروجه بنفسه لقبيلة غطفان وإرسال لهم السرايا التأديبية عشان إللي عملوه في الأحزاب، \nعُيينة بن حصن الأحمق المُطاع سيد قبيلة غطفان يتعظ ويسكت بقى\nأبدا\nاجتمع مع مجموعة من غطفان واتفق معاهم إنهم يكونوا ضد رسول الله ﷺ ويهجموا على المدينة\nوصل الخبر لرسول الله ﷺ فجهز رسول الله ﷺ سرية من ثلاثمائة رجل وخلّى قائدهم بشير بن سعد مرة تانية وقال لهم يتوجهوا إلى منطقة يُمْن وجَبار في شهر شوال عشان يقضوا على التجمع ده،\nفكانت السرية بتمشي بالليل وترتاح بالنهار عشان محدش يعرف عنهم حاجة ويهجموا عليهم فجأة،\nفلما وصلوا ملقوش غير الرعاة، فأخذوا الأغنام والمواشي، وهرب الرعاة وراحوا أخبروا قومهم إللي كانوا متجمعين لقتال رسول الله ﷺ،\nفراحوا هربوا هم كمان لبلادهم، ومحصلش قتال بينهم وبين المسلمين، وأخذ المسلمون الأغنام وأسروا رجلين من المشركين ورجعوا للمدينة،\nالرجلين إللي تم أسرهم دول سبحان الله أسلموا،\nتدبير ربنا عجيب فعلا\nيعني عشان الرجلين دول يُسلموا ربنا قدّر خروج السرية من المدينة وإنها تروح وتأسر الرجلين دول بالذات عشان يدخلوا في الإسلام وينجوا أنفسهم من النار\nدلوقتي احنا اتكلمنا عن أربع سرايا وفاضل سريتين، والسريتين هيخرجوا على آخر السنة السابعة، فهنتكلم عنهم لما ييجي وقتهم إن شاء الله،\nفي نفس الوقت إللي كانت السرايا بتخرج، الدنيا مكنتش واقفة في المدينة،\nيعني رسول الله ﷺ كان مستمر في الدعوة وتعليم الصحابة، وكانت الأحداث مستمرة، من الأحداث إللي حصلت في المدينة نزول آية:\n\" لِّلَّهِ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ ۗ \n《وَإِن تُبْدُوا مَا فِي أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ اللَّهُ》 ۖ فَيَغْفِرُ لِمَن يَشَاءُ وَيُعَذِّبُ مَن يَشَاءُ ۗ وَاللَّهُ عَلَىٰ كُلِّ شَيْءٍ قَدِيرٌ \"\nالآية دي معناها إيه\nيعني أي حد هيفكر في الشر من غير حتى ما يعمله ربنا هيحاسبه عليه، \nيعني لو حد مثلا فكر في قتل واحد من الناس مجرد تفكيره ده أو بس يخطر الكلام ده على باله؛\nربنا يحاسبه على التفكير، مجرد ما حد يفكر في معصية؛ ربنا هيحاسبه،\nالصحابة لما سمعوا الآية دي اشتد عليهم الهم والغم\nخلونا نحط نفسنا مكانهم كده، تخيلوا كم مرة في اليوم الواحد فينا بييجي في باله إنه يعمل حاجة غلط وبيدفعها ويقاوم نفسه،\nوالخواطر دي أصلا محدش يقدر يتحكم فيها،\nفسواء الإنسان أخفى الخواطر دي أو أظهرها فهو هيتحاسب على حسب الآية إللي نزلت دي،\nيعني أنا كده رايح في داهية...رايح في داهية مفيش مفر\nالصحابة يا جماعة كانوا شديدي المراقبة لسلوكهم،\nوكانوا فوق كل ده على درجة عالية من الالتزام بأحكام الشرع،\nواحنا شوفنا أمثلة لشدة طاعتهم وامتثالهم لأوامر الله، فلما جاءهم أمر زي ده، بقوا مش عارفين يعملوا إيه،\nبقوا بين نارين، لا قادرين ينفذوا أمر ربنا لأنه فوق طاقتهم،\nولا هم قادرين يرفضوا أمر ربنا ويعترضوا عليه،\nفأبو بكر وعمر وعثمان ومجموعة كبيرة من الصحابة راحوا لرسول الله ﷺ ونزلوا على ركبهم وقالوا لرسول الله ﷺ بكل ألم:\nأي رسول الله! كُلِّفنا من الأعمال ما نُطِيق:\n الصلاة، والصيام، والجهاد، والصدقة، وقد أُنزلت عليك هذه الآية ولا نُطيقها،\nيا رسول الله! هَلَكنا، إن كنا نُؤاخذ بما تكلمنا، وبما نعمل، فأما قلوبنا فليست بأيدينا\nيعني الصحابة بيقولوا لرسول الله ﷺ: ربنا كلفنا بالأعمال الصالحة زي الصلاة والصيام والصدقة والجهاد والأعمال دي احنا نقدر عليها،\nلكن الآية إللي نزلت دي منقدرش ننفذها، احنا كده هنهلك يا رسول الله، يعني احنا نقدر نتحكم في كلامنا وأفعالنا لكن قلوبنا منقدرش نتحكم فيها\nرسول الله ﷺ رد عليهم رد، أنا نَفسِي طول عمري كنت بستغرب رد رسول الله ﷺ على الصحابة في الموقف ده\nقال لهم بكل حزم:\n\"أتريدون أن تقولوا كما قال أهل الكتابين من قبلكم: سمعنا وعصينا، بل قولوا: سمعنا وأطعنا\nيعني بيقول لهم انتم عايزين تعملوا زي بني إسرائيل لما جاءهم أمر من ربنا قالوا سمعنا وعصينا؟!!\nقولوا سمعنا وأطعنا\nيعني هم أصلا جايين متألمين وهو ﷺ عارف كويس أوي أد إيه هم حريصين على طاعة الله ورسوله وتنفيذ أوامره،\nفالمفروض إنه يهوّن عليهم ويتلطف معاهم ويشجعهم على الإلتزام بأوامر ربنا، طبعا ده من وجهة نظرنا،\nلكن هو اتكلم هنا بكل حزم، بعكس المتوقع\nطب ليه\nرسول الله ﷺ والله أعلم بيعلم الصحابة وبيعلمنا معاهم التسليم التاااام لأوامر الله، \nجاءك الأمر متعترضش سلم بأمر بالله بدون أي نقاش أو جدال، خذ الكتاب بقوة\nيعني لو الواحد فينا شاف إن أوامر ربنا صعبة عليه أو مش قادر ينفذها أو مش فاهم الحكمة منها ياخد الأمور بحزم ويسلم لله ويقول لربنا سمعت وأطعت يارب،\nويبقى عنده ثقة تامة في الله إنه وقت ما هيجاهد نفسه ويقدم أوامر ربنا على نفسه هييجي الفرج والأمور هتتيسر،\nفي أوقات كتير محتاجين فيها الحَزْم وإننا ناخد الأمور بقوة أكتر من احتياجنا للين،\nوهو ده إللي رسول الله ﷺ عمله هنا، الموقف هنا موقف حزم، سلموا أمركم لله الأول وبعدين بقى نبقى نشوف استفساراتكم ونشوف هنعالج المشكلة إزاي\nالصحابة لما شافوا رد فعل رسول الله ﷺ وإن ده أمر نافذ مفهوش مجال للمفاوضة وطاعة ربنا مفيهاش مفر،\nسلموا لأمر الله وقالوا:\nسمعنا وأطعنا\nقالوها وهم كانوا لسه محتارين ولسه خايفين،\nولسه حاسين بشيء من الضياع ولسه مش عارفين هيحلوا المشكلة دي إزاي وهيتحكموا في خواطرهم إزاي،\n يعني حالة توهان شديدة جدا ومع ذلك قالوا سمعنا وأطعنا\nمجرد ما نطقوها، فورا نزل التخفيف عليهم، ونزلت الآية إللي وراها على طول:\n\"آمَنَ الرَّسُولُ بِمَا أُنزِلَ إِلَيْهِ مِن رَّبِّهِ وَالْمُؤْمِنُونَ ۚ كُلٌّ آمَنَ بِاللَّهِ وَمَلَائِكَتِهِ وَكُتُبِهِ وَرُسُلِهِ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِ ۚ وَقَالُوا سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ الْمَصِيرُ ۩\nلَا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا اكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَا إِن نَّسِينَا أَوْ أَخْطَأْنَا ۚ \nرَبَّنَا وَلَا تَحْمِلْ عَلَيْنَا إِصْرًا كَمَا حَمَلْتَهُ عَلَى الَّذِينَ مِن قَبْلِنَا ۚ رَبَّنَا وَلَا تُحَمِّلْنَا مَا لَا طَاقَةَ لَنَا بِهِ ۖ \nوَاعْفُ عَنَّا وَاغْفِرْ لَنَا وَارْحَمْنَا ۚ أَنتَ مَوْلَانَا فَانصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ \"\nخلاص لا يكلف الله نفسا إلا وسعها وطاقتها، ربنا يعلم إن الخواطر دي محدش هيقدر يتحكم فيها، فأنزل التخفيف،\nوبقى حديث النفس معفو عنه إلا لو الإنسان تكلم به أو عمله،\nورسول الله ﷺ قال:\n\"إن الله تجاوز لي عن أمتي ما حدّثت به أنفسها، ما لم تكَلّم، أو تعمل\"\nوالهدف من نزول الآية الصعبة دي إن ربنا أراد إنه يختبر الصحابة رضي الله عنهم، \nولأن ربنا يعلم إن في ناس هتيجي بعدين هيعترضوا على كل حاجة من أوامر ربنا،\nوإللي هييجي يقول أنا لازم اقتنع الأول،\nوإللي عايز حل لمشاكله قبل ما يسمع كلام ربنا وإللي بيعترض عشان الاعتراض،\nقليل جدا دلوقتي لما نيجي نقول لحد على أمر من أوامر ربنا وينفذه من غير ما يعترض ويناقش ويفرهدْنا معاه\nفربنا بيوري كل الأجيال إللي جت بعد الصحابة النموذج الأمثل في التسليم لأوامر الله،\nواحنا عارفين إن ربنا مش بيعاقب ولا بيجازي بسابق علمه فينا، يعني احنا لازم نعمل العمل سواء خير أو شر عشان ربنا يجازينا عليه،\nوإلا فربنا يعلم الغيب ويعلم احنا هنعمل إيه وممكن يحاسبنا على كده، لكن هو بيورينا أفعالنا عشان نبقى شهداء على أنفسنا ومندّعيش إن ربنا ظلمنا والعياذ بالله،\nفكان الاختبار ده من أشد الاختبارات على الصحابة، وكانت النتيجة إنهم نجحوا فيه، وبقوا مَضرب المثل في الطاعة المُطلقة لله ورسوله\nولو تفتكروا لما اتكلمنا عن الإسراء والمعراج في الجزء الرابع والثلاثين، وقلنا إن ربنا كلم رسول الله ﷺ وأعطاه هديتين،\nكان منهم خواتيم سورة البقرة، \nإللي هم الآيتين إللي قلناهم دول\nوقلنا إن ربنا قال لرسول الله ﷺ  إنه أعطاه خواتيم سورة البقرة، لكن كانت إيه هي الآيات دي وتفصيلها إيه؟ \nمكنش لسه وقتها جه، واحنا دلوقتي في وقتها،\nوقلنا فضل خواتيم سورة البقرة، خلونا نفتكرهم كده سريعا:\nمن يقرأ خواتيم سورة البقرة في كل ليلة قبل ما ينام كَفَتَاه، يعني:\n♡تُجزئه عن قيام الليل \n♡تُجزئه عن قراءة القرآن بشكل عام\n♡تكفيان الإنسان من كل سوء\n♡تكفيان من الثواب، يعني تحقق لنا من الثواب إللي يعادل سيئات اليوم\n☆عايزين بقى نفهم نقطة مهمة جدا بالنسبة للأمور إللي بتيجي على بالنا،\n وهي إننا محتاجين نفرق بين إللي بييجي على بالنا من خواطر سيئة وبين النية والعزم على عمل الخواطر دي،\nبمعنى: \nأنا ممكن ييجي على بالي إني أسرق أو أقتل أو أعمل أي معصية، لكن أنا معملتش ومنويتش فعلا العمل ده،\nالخاطرة دي بقى هي إللي ربنا مش بيحاسبنا عليها وإللي رسول الله ﷺ قال إن احنا غير مؤاخذين عليها،\nماشي كده\nالنية والعزم بقى نقطة تانية خالص،\nخلونا كده نشوف كم حديث لرسول الله ﷺ عشان نفهم المعنى ده، رسول الله ﷺ قال للصحابة :\n\"إنما الأعمال بالنيات وإنما لكل امرئٍ ما نَوى\"\n◇الأعمال بالنيات:\n يعني عشان آخد أجر وثواب على عمل عملته لازم يكون عندي نية صالحة،\nمثلا واحد تصدق على فقير لأنه عايز أجر الصدقة، فهنا هياخد أجر،\nطيب نفس الرجل تصدق بنفس الصدقة لكن نيته أو إللي جاء في باله كان إنه بيتصدق عشان الناس تمدحه،\n هنا هياخد ذنب\nفهنا إللي حدد الفرق بين الأجر والثواب وبين الذنب كان الخاطرة أو النية إللي دفعت الإنسان للصدقة\n◇وإنما لكل امرئ ما نوى:\nيعني نيتي هتحاسب عليها من غير ما أعمل أي عمل، \nيعني مثلا واحد معندوش مال زيادة يتصدق بيه على الفقراء،\nوشايف واحد غني بيتصدق على الفقراء وبيكرمهم وبيطعمهم، فهو يقول أمّا أنا لو معايا فلوس زي الرجل الغني ده كنت أطعمت كل الفقراء، وأكرمتهم وعملت زي الرجل الغني ده، هنا الرجل الفقير هياخد نفس أجر الرجل الغني 《بالنية》\nواحد تاني شايف واحد غني كل يوم ينتهك حرمات الله سواء بشرب الخمر أو الزنا أو أي معاصي، فالرجل يقول أما أنا لو معايا فلوس زيه كنت خربتها وعملت... وعملت... زي ماهو بيعمل، \nالرجل ده هياخد نفس الذنب بتاع الرجل الغني العاصي مع إنه معملش حاجة وكل ده بسبب النية والعزم\nوشوفوا رسول الله ﷺ قال للصحابة إيه في نفس معنى كلامنا قال:\n\" إِنَّمَا الدُّنْيَا لِأَرْبَعَةِ نَفَرٍ: \n♧عَبْدٍ رَزَقَهُ اللَّهُ مَالًا وَعِلْمًا فَهُوَ يَتَّقِي فِيهِ رَبَّهُ، وَيَصِلُ فِيهِ رَحِمَهُ، وَيَعْلَمُ لِلَّهِ فِيهِ حَقًّا، فَهَذَا بِأَفْضَلِ المَنَازِلِ، \n♧وَعَبْدٍ رَزَقَهُ اللَّهُ عِلْمًا وَلَمْ يَرْزُقْهُ مَالًا فَهُوَ صَادِقُ النِّيَّةِ يَقُولُ: \nلَوْ أَنَّ لِي مَالًا لَعَمِلْتُ بِعَمَلِ فُلَانٍ فَهُوَ بِنِيَّتِهِ فَأَجْرُهُمَا سَوَاءٌ،\n♧وَعَبْدٍ رَزَقَهُ اللَّهُ مَالًا وَلَمْ يَرْزُقْهُ عِلْمًا،\n فَهُوَ يَخْبِطُ فِي مَالِهِ بِغَيْرِ عِلْمٍ لَا يَتَّقِي فِيهِ رَبَّهُ، وَلَا يَصِلُ فِيهِ رَحِمَهُ، وَلَا يَعْلَمُ لِلَّهِ فِيهِ حَقًّا، فَهَذَا بِأَخْبَثِ المَنَازِلِ،\n ♧وَعَبْدٍ لَمْ يَرْزُقْهُ اللَّهُ مَالًا وَلَا عِلْمًا فَهُوَ يَقُولُ:\n لَوْ أَنَّ لِي مَالًا لَعَمِلْتُ فِيهِ بِعَمَلِ فُلَانٍ فَهُوَ بِنِيَّتِهِ فَوِزْرُهُمَا سَوَاءٌ\"\nيعني رسول الله ﷺ بيقول لنا إن البشر مش هيخرجوا من الأربع حالات دي: \nواحد عنده علم وعنده مال، فهو بيتقي الله وبيصل رحمه وعارف حق ربنا فيه، فده أحسن واحد منزلة،\nوالثاني عنده علم ومعندوش مال، وشايف إللي عنده علم ومال بيعمل إيه فيتمنى المال عشان يعمل زي صاحبه وهو صادق النية، فربنا يرزقه بنفس أجر صاحبه\nالثالث واحد جاهل ومعندوش علم ولكنه عنده مال ، فمش بيراعي حق ربنا ولا بيَصل رحمه بل بيستعين بالمال على معصية الله، فالنوعية دي هي أخبث الناس منزلة،\nوالأخير ده بقى إللي لا عنده علم ولا عنده مال ولا أي حاجة خالص، \nوشايف الغني الفاجر ده وشايف معاصيه فيقول أما أنا لو عندي زي أموال فلان كنت عملت زيه، فيهاخد نفس ذنبه\nوالله يا جماعة لو ركزتم شوية وبصيتوا على واقعنا هتلاقوا أكثر الناس للأسف هم آخر صنفين\nعارفين إللي فرق بين الأول والثاني والثالث والرابع إيه؟\nالعلم\nماهو الرجل الغني ده هيعرف حق ربنا إزاي من غير ما يتعلم،\nولّا الرجل الرابع إللي محيلتهوش حاجة إزاي هيعرف إن مجرد أمنيته هتوديه في داهية وهتخليه ياخد نفس ذنب الرجل الثالث ده إلا بالعلم\nفخُلاصة الكلام في النقطة دي يا جماعة إن ربنا أه مش بيحاسبنا على الخواطر إللي بتيجي في بالنا مادام هي مجرد خواطر عابرة بندفعها،\nلكن مجرد ما الخواطر دي تحولت لنية وعزم وأمنية وأنا نفسي أعمل كذا، كده هيبدأ الحساب سواء بالحسنات أو بالسيئات كل واحد على حسب نيته \n♡الموضوع ده مهم لأن في ناس كتير عندها فيه لخبطة، فلو في أي نقطة مش واضحة أو في استفسار ياريت تسيبوه في التعليقات\nوإن شاء الله أرد عليه في بداية الجزء الجاي، وإللي عنده برده أي سؤال أو أي نقطة مش واضحة في أي حلقة اتكلمنا فيها، يسيبه في التعليقات وأنا هرد إن شاء الله في بداية كل جزء جديد \nمن الأحداث إللي حصلت برده في المدينة، إن رسول الله ﷺ شاف رؤيا، فقعد يحكيها للصحابة،\nوكان من عادة رسول الله ﷺ إنه كان بيسأل الصحابة كتير هل في حد فيكم شاف رؤيا؟!\nلأن الرؤيا جزء من أجزاء النبوة، والرؤيا ممكن يكون فيها إِخبار عن غيب مستقبلي، أو فيها تحذير من شيء، \nوإذا كانت من رجل مؤمن صادق فبتكون من أصدق ما يكون، \nورسول الله ﷺ كان بيقول للصحابة إن أصدَقهم رؤيا أصدقهم حديثًا،\nيعني كل ما كان الإنسان صادق في كلامه؛ رؤياه تكون في غاية الصدق، \nوأحيانا بتقع زي ما شافها بالضبط في الرؤيا، \nفكان لما حد بيشوف رؤيا بيقولها لرسول الله ﷺ ورسول الله ﷺ كان بيفسرها لهم،\n إللي كان متابع الموضوع ده واحد من صِغار الصحابة وهو عبد الله بن عمر بن الخطاب رضي الله عنهما،\nوكان بيتمنى دايما إنه يشوف رؤيا عشان يحكيها لرسول الله ﷺ، \nوكان عبد الله بينام في المسجد؛ لأنه كان صغير وغير متزوج فمكنش عنده مسؤوليات يعني\nففي يوم من الأيام كان نايم وشاف رؤيا....إيه الرؤيا إللي شافها عبد الله بن عمر وكان إيه تفسيرها؟\nوإيه الرؤيا إللي رسول الله ﷺ شافها هو كمان وحكاها للصحابة؟\nده إللي هنعرفه الجزء الجاي إن شاء الله \n☆"}, {"n": 171, "l": "الجزء 145 | احداث السنه السابعه من الهجرة | رؤيا رسول الله عن أهل البرزخ", "u": "https://www.facebook.com/groups/710210019782034/permalink/836523090484059/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#رؤيا_رسول_الله_عن_أهل_البرزخ\nوقفنا المرة إللي فاتت عند عبد الله بن عمر بن الخطاب لما كان نايم في المسجد وشاف رؤيا،\nشاف عبد الله بن عمر في الرؤيا إن في مَلكين أخذوه وذهبوا به إلى النار، يقول:\n\" فَرَأَيْتُ في المَنَامِ كَأنَّ مَلَكَيْنِ أخَذَانِي فَذَهَبَا بي إلى النَّارِ، فَإِذَا هي مَطْوِيَّةٌ كَطَيِّ البِئْرِ، وإذَا لَهَا قَرْنَانِ كَقَرْنَيِ البِئْرِ\"\nعبد الله بن عمر بيوصف شكل النار وبيقول إنها كانت مَطْويَّةٌ طَيَّ البئرِ، يعني مبنية من الجوانب بالطوب، إللي هو شكل البئر المعروف، والبئر لو مكنتش مبنية بالطوب من على الجوانب بيبقى اسمها 《القَلِيب》،\nوبيقول إنها كان لها قرنين زي قرنين البئر، والمقصود بقرنين البئر إللي هم الخشبتين إللي بيكونوا على جانبي البئر وبيربط بينهم خشبة بيتعلق عليها بكرة الحبل إللي بيكون مربوط فيه الدلو أو الجردل، أكيد شوفتم شكل البئر في أي كارتون ولّا حاجة\nالمهم،\nعبد الله بن عمر بيقول إنه لما وصل للنار دي شاف بداخلها ناس يعرفهم، فخاف واترعب وقعد يقول : أعوذ بالله من النار...أعوذ بالله من النار\n\" وإذَا فِيهَا نَاسٌ قدْ عَرَفْتُهُمْ فَجَعَلْتُ أقُولُ أعُوذُ باللَّهِ مِنَ النَّارِ، أعُوذُ باللَّهِ مِنَ النَّارِ\"\nفقابلهم مَلك ثالث فقال لعبد الله بن عمر:  لم تُرَعْ\nيعني متخافش متخافش، مفيش ضرر عليك ولا فزع،\nفلما استيقظ راح عبد الله بن عمر لأخته حفصة زوجة رسول الله ﷺ وحكى لها الرؤيا، فحفصة حكت لرسول الله ﷺ الرؤيا بتاعة عبد الله،\nفقال لها رسول الله ﷺ في تفسير الرؤيا :\n《نِعْمَ الرَّجُلُ عبدُ اللَّهِ لو كانَ يُصَلِّي باللَّيْلِ》\nيعني رسول الله ﷺ بيقول إن عبد الله بن عمر هيبقى رجل صالح لو كان بيصلي قيام ليل،\nفلما حفصة رضي الله عنها وصّلت الكلام لعبد الله بن عمر، فمبقاش يسيب قيام الليل أبدا ومكنش بينام في الليل إلا قليل\n☆نتعلم من قصة عبد الله بن عمر إن قيام الليل سبب في نجاة الإنسان من النار\nوبما إننا بنتكلم عن قيام الليل، فممكن ناس تكون فاهمة إنها لازم تكون تفضل تصلي طول الليل،\nوفي ناس بتبقى نفسها تصلي قيام ليل بس بيكون عندها شغل وأولاد وتعبانين ومحتاجين للنوم والراحة، طيب إيه الحل\nشوفوا، \nقيام على قدر الاستطاعة، يعني الواحد ممكن يصلي ركعتين وممكن يصلي إحدى عشرة ركعة،\nمش مطلوب نصلي بالبقرة وآل عمران عشان يبقى كده أقمنا الليل\nطبعا إللي يقدر يعمل كده مفيش مشكلة خالص بالعكس دي حاجة كويسة،\nلكن أنا بتكلم على إللي مبيقدرش أو عنده ظروف\nخلينا نشوف حديث رسول الله ﷺ الرائع إللي بيسهل علينا وبيدينا أمل إن بإمكان كل واحد فينا على اختلاف ظروفه يقدر يصلي قيام ليل، يقول ﷺ:\n\"مَنْ قَامَ بِعَشْرِ آيَاتٍ لَمْ يُكْتَبْ مِنْ الْغَافِلِينَ ، وَمَنْ قَامَ بِمِائَةِ آيَةٍ كُتِبَ مِنْ الْقَانِتِينَ ، وَمَنْ قَامَ بِأَلْفِ آيَةٍ كُتِبَ مِنْ الْمُقَنْطِرِينَ\"\n=يعني إللي هيصلي ركعتين بعشر آيات مش هيكتب من الغافلين عن ذكر الله، زي الصلاة بسورة الفلق وسورة الناس، الإتنين مع بعض إحدى عشرة آية\n=وإللي هيصلي بمائة آية هيتكتب عند ربنا من القانتين، والقانتين معناها المُطِيعين الساكتين الخاضعين الخاشعين لله،\nوسورة القلم والحاقة مع بعض حوالي مائة وخمسة آيات\n=وإللي هيصلي بألف آية هيتكتب عند ربنا من المُقنطرين،\nوالمقنطرين معناها المُكثِرِين من الأجر، \nيعني زي الناس إللي بيزودوا أموالهم، كذلك المقنطرين بيزودوا أجرهم،\nوجزء تبارك وجزء عم مع بعض مجموعهم يساوي ألف آية تقريبا\n فكل واحد يختار على حسب وقته واستطاعته\n◇طيب امتى نصلي، هل بعد العشاء ولّا قبل الفجر\nاحنا عندنا اختيارين:\nإما نصلي بعد العشاء مباشرة وقبل ماننام القيام وبعدين نصلي الوتر زي ما أبو بكر الصديق رضي الله عنه كان بيعمل،\nأو نصلي في وقت السحر إللي هو قبل الفجر بحوالي ساعة ونختم الصلاة بالوتر زي ما عمر بن الخطاب رضي الله عنه كان بيعمل،\nفنصلي ركعتين وبعدهم الشفع والوتر، أو تسع ركعات ومعاهم الشفع والوتر ويبقى كده إحدى عشرة ركعة، كل واحد على حسب اجتهاده وظروفه،\nوزي ما رسول الله ﷺ قال:\n\"أحبّ الاعمال إلى الله أَدْوَمُها وإن قَل \"\nيعني أكثر الأعمال إللي ربنا يحبها إللي احنا نكون مداومين عليها، حتى لو كانت قليلة، يعني لو الواحد هيصلي كل يوم بعشر آيات أحسن عند ربنا من إللي يصلي بمائة آية مرة واحدة بس وميكملش\n♡ومتنسوش النية، يعني احنا بنصلي قيام الليل ليه،\nلازم تكون نيتنا لله، يعني عشان ربنا يرضى علينا وينجينا من النار،\nوطبعا النية في القلب مش بنقولها بلساننا خالص\nونصيحة أخوية\nلما تصلوا قيام الليل خلوا الموضوع ده خَبِيئة بينكم وبين ربنا متقولوش عليها لحد \nفالخبيئة الصالحة تجارة رابحة\nأولا: عشان الإخلاص، \nثانيا: عشان العين والحسد\nوطبعا المفروض إننا نخبي كل أعمالنا الصالحة سواء صيام أو صدقة أو قراءة قرآن أو حتى حفظ القرآن،\nلأن كل ما كان العمل خفيا كان إلى الإخلاص أقرب، وعن العين والحسد أبعد\n☆وهنا هيطلع لنا سؤال ناس كتير بتسأل عنه،\nهل لو أنا قلت لحد على طاعة وبعدين مبقتش أعملها يبقى إللي قلتله ده حسدني، أو أصابني بعين\nده احتمال وارد من ضمن الاحتمالات وخصوصا إن محدش بينفع أو يضر بذاته، لكن كل حاجة بإذن الله\nفمش شرط يكون إن هو ده السبب الرئيسي؛ لأن ممكن والواحد فينا بيحكي عن عبادته دخل في قلبه إعجاب بعمله وفخر أو دخل في قلبه رياء\nوخصوصا إن الرياء والعجب والحاجات دي بتكون أخفى من دبة النملة، يعني احنا مش بنحس بدبة النملة فما بالكم باللي أخفى من دبة النملة هنحس بيه إزاي\nوطبعا العُجب والرياء من محبطات الأعمال، يعني الواحد يجتهد ويتعب وفي الآخر ميلاقيش ثواب الأعمال دي بالعكس ده يتحاسب عليها\nفربنا من رحمته بينا خلانا نتوقف عن الأعمال دي لحد ما نعرف الغلط فين ونصحح نيتنا\nفقبل ما نفكر في الحسد والعين نفكر في العجب والرياء ونعالجه ونستغفر ونراجع نيتنا،\nوبعدين نبقى نشوف موضوع الحسد والعين، والأحسن بقى من كل وجع الدماغ ده إننا نخبي أعمالنا الصالحة ومنقلش لحد عليها، ولو في أعمال ظاهرة لازم الناس هتشوفها يبقى نركز جدا جدا جدا في إننا نخلص النية لله\nكده يبقى خلصنا الرؤيا بتاعة عبد الله بن عمر رضي الله عنه،\nعايزين بقى نعرف  الرؤيا بتاعة رسول الله ﷺ شاف فيها إيه، \nواستعدوا للكلام لأن الأحداث إللي رسول الله ﷺ شافها صعبة أوي ومجرد تخيلها؛ الواحد قلبه بيوجعه\nبيحكي رسول الله ﷺ للصحابة بعد صلاة الصبح وبيقول إنه جاءه الليلة إللي فاتت في المنام ملكين، هما جبريل وميكائيل، فأخذوه معاهم وانطلقوا،\nقال رسول الله ﷺ:\n\"إنَّه أتانِي اللَّيْلَةَ آتِيانِ، وإنَّهُما ابْتَعَثانِي، وإنَّهُما قالا لي انْطَلِقْ، وإنِّي انْطَلَقْتُ معهُما\"\nيعني رسول الله ﷺ رأى وهو نايم إن الملكين جاءوه وأيقظوه وأخذوه، وكل ده داخل الرؤيا، رسول الله ﷺ مصحيش،\nزي ما الواحد فينا بيحلم إنه كان نايم وبعدين صحي في الحلم وحصلت معاه أحداث وبعدين يصحى بقى في الحقيقة،\nفده كان موقف رسول الله ﷺ بالضبط، جاءه الملكان وأخذوه معاهم ومشيوا لحد ما وصلوا لأرض مستوية، شاف فيها رجل نايم على الأرض، وواحد تاني واقف عند رأسه وماسك صخرة في إيده،\nفاللي ماسك الصخرة ده رمى الصخرة على رأس الرجل النايم في الأرض، فرأسه اتكسرت واتساوت بالأرض،\nوإنَّا أتَيْنا علَى رَجُلٍ مُضْطَجِعٍ، وإذا آخَرُ قائِمٌ عليه بصَخْرَةٍ، وإذا هو يَهْوِي بالصَّخْرَةِ لِرَأْسِهِ فَيَثْلَغُ رَأْسَهُ\"\nوطبعا لكم أن تتخيلوا صوت الصراخ من الألم عامل إزاي، ربنا يعافينا وإياكم\nالمهم،\nالصخرة ادحرجت وراحت بعيد، فالرجل القائم راح يجيب الصخرة، \nوعلى ما راح يجيبها كان رأس الرجل إللي اتكسر رجع تاني زي ماهو، \nفيرجع ويرمي الصخرة تاني على رأس الرجل النائم في الأرض ويتكسر رأسه والحجر يتدحرج ويروح يجيبه وهكذا\n\"فَيَتَدَهْدَهُ الحَجَرُ ها هُنا، فَيَتْبَعُ الحَجَرَ فَيَأْخُذُهُ، فلا يَرْجِعُ إلَيْهِ حتَّى يَصِحَّ رَأْسُهُ كما كانَ، ثُمَّ يَعُودُ عليه فَيَفْعَلُ به مِثْلَ ما فَعَلَ المَرَّةَ الأُولَى\" \nرسول الله ﷺ اتصدم من المنظر، وسأل الملكين، وقال لهم :\n سبحان الله ما هذان؟!!\nيعني إيه حكاية الرجلين دول وإيه بيحصل ده\nفقالا له: انطلق انطلق\nيعني كأنهم بيقولوا، تعال تعال انت لسه شوفت حاجة، في حاجات تانية قُدام،\n\"قالَ: قُلتُ لهما: سُبْحانَ اللَّهِ ما هذانِ؟ قالَ: قالا لِي: انْطَلِقِ انْطَلِقْ\"\nفانطلق معاهم رسول الله ﷺ لحد ما وصلوا لرجل قاعد وواحد تاني واقف عنده وفي إيده كَلُّوب من حديد، والكَلُّوب ده حديدة معووجة كده عاملة زي الخطاف،\nشوفتم صورة أي قرصان إللي بيكون إيده مقطوعة وحاطط مكانها حديدة عاملة زي علامة الاستفهام كده ؟\nأهه الكلّوب يشبه الخطاف ده\n\"فانْطَلَقْنا، فأتَيْنا علَى رَجُلٍ مُسْتَلْقٍ لِقَفاهُ، وإذا آخَرُ قائِمٌ عليه بكَلُّوبٍ مِن حَدِيدٍ\"\nفالرجل القائم إللي معاه الكَلّوب، بييجي ناحية وجه الرجل اليمين ويشَرشَر فمه إلى قفاه، يعني يشق فمه ويقطعه من أول الطرف لحد ما يوصل لرقبته من ورا،\nويشرشر أنفه لحد قفاه ويشرشر عينه لحد قفاه، \n\"وإذا هو يَأْتي أحَدَ شِقَّيْ وجْهِهِ فيُشَرْشِرُ شِدْقَهُ إلى قَفاهُ، ومَنْخِرَهُ إلى قَفاهُ، وعَيْنَهُ إلى قَفاهُ\"\nولما يخلص الناحية اليمين ينتقل للناحية الشمال ويعمل فيها نفس إللي عمله في الناحية اليمين،\n\"ثُمَّ يَتَحَوَّلُ إلى الجانِبِ الآخَرِ فَيَفْعَلُ به مِثْلَ ما فَعَلَ بالجانِبِ الأوَّلِ\"\nوعلى ما يخلص الناحية الشمال، الناحية اليمين تكون رجعت صحيحة زي ما هي، \nويفضل يعيد نفس الفعل في كل ناحية،\n\"فَما يَفْرُغُ مِن ذلكَ الجانِبِ حتَّى يَصِحَّ ذلكَ الجانِبُ كما كانَ، ثُمَّ يَعُودُ عليه فَيَفْعَلُ مِثْلَ ما فَعَلَ المَرَّةَ الأُولَى\"\nوطبعا مش محتاجين نقول كمية الألم إللي الرجل إللي بيتعمل فيه الكلام ده بيحسها،\nالواحد لما بس بيتجرح جرح شديد شوية بيبقى مش قادر يستحمل، ده بقى كأنه بيتعمل له عمليات في وشه بدون بنج\nفرسول الله ﷺ واقف بيشوف المنظر ومندهش جدا، وقال للملكين: سبحان الله ما هذان؟!!\nفقال له الملكان: انطلق انطلق\nفانطلق الثلاثة ووصلوا للمكان الثالث، وكان عامل زي الفرن، واسع من تحت وضيق من فوق،\n\"فأتَيْنا علَى مِثْلِ التَّنُّورِ أعْلَاهُ ضَيِّقٌ وأَسْفَلُهُ واسِعٌ\"\nوسمع رسول الله ﷺ أصوت جاية من التنور، أو من الفرن ده،\nفتوجه ناحيته ونظر داخله فشاف فيه رجال ونساء عُراة يعني عريانين مش لابسين أي ملابس، وفي نار مولعة تحتهم،\n\"فإذا فيه لَغَطٌ وأَصْواتٌ قالَ: \nفاطَّلَعْنا فِيهِ، فإذا فيه رِجالٌ ونِساءٌ عُراةٌ، وإذا هُمْ يَأْتِيهِمْ لَهَبٌ مِن أسْفَلَ منهمْ\"\nأول ما النار دي تشتد يصيحوا ويصرخوا ويرتفعوا لفوق، وأول ما يقربوا يخرجوا من الفرن ده، النار تخمد فينزلوا تاني لأسفل الفرن، \n\"فَإِذَا اقْتَرَبَ ارْتَفَعُوا حتَّى كَادَ أنْ يَخْرُجُوا، فَإِذَا خَمَدَتْ رَجَعُوا فِيهَا\"\nوالنار تشتد تاني ويصرخوا ويرتفعوا لأعلى وأول ما يوصلوا إنهم يخرجوا، النار تخمد وينزلوا للأسفل تاني، وهكذا\n\"فإذا أتاهُمْ ذلكَ اللَّهَبُ ضَوْضَوْا \"\nفقال لهم رسول الله ﷺ: ما هؤلاء؟!!\nفقال له الملكان: انطلق انطلق\nفانطلق الثلاثة لحد ما وصلوا لنهر من دم، لقوا فيه رجل بيسبح،\n\"فانْطَلَقْنا، فأتَيْنا علَى  نَهَرٍ مِن دَمٍ، وإذا في النَّهَرِ رَجُلٌ سابِحٌ يَسْبَحُ\"\nوفي رجل تاني واقف على شاطئ النهر وجامع معاه حجارة كثيرة، \n\"وإذا علَى شَطِّ النَّهَرِ رَجُلٌ قدْ جَمع عِنْدَهُ حِجارَةً كَثِيرَةً\"\nأول ما الرجل إللي بيسبح ده يوصل للشاطئ،\nيقوم فاتح فمه للرجل إللي معاه الحجارة فيقوم رامي الحجارة في فمه،\n\"وإذا ذلكَ السَّابِحُ يَسْبَحُ ما يَسْبَحُ، ثُمَّ يَأْتي ذلكَ الذي قدْ جَمع عِنْدَهُ الحِجارَةَ، فَيَفْغَرُ له فاهُ فيُلْقِمُهُ حَجَرًا\"\nفالرجل يروح يسبح مرة ثانية في نهر الدم، وبعدين يرجع للرجل إللي معاه الحجارة ولما يوصل له يقوم فاتح فمه فيقوم رامي الحجارة في فم السابح ده، وهكذا\n\"فَيَنْطَلِقُ يَسْبَحُ، ثُمَّ يَرْجِعُ إلَيْهِ كُلَّما رَجَعَ إلَيْهِ فَغَرَ له فاهُ فألْقَمَهُ حَجَرًا\" \nكل ده ورسول الله ﷺ شايف، فسأل الملكين: مين الرجلين دول\nفقال له الملكان:\nانطلق انطلق\nفانطلقوا وراحوا عند رجل شكله وحش جدا، وعنده نار بيحُشَّها، يعني بيزيد إشعالها وبيلف حواليها،\n\"فانْطَلَقْنا، فأتَيْنا علَى رَجُلٍ كَرِيهِ المَرْآةِ، كَأَكْرَهِ ما أنْتَ راءٍ رَجُلًا مَرْآةً، وإذا عِنْدَهُ نارٌ يَحُشُّها ويَسْعَى حَوْلَها\"\nعارفين زي مثلا لما نيجي نولع فحم أو خشب ويبقى معانا زي حديدة كده نقعد نحرك في الخشب أو الفحم عشان ناره تزيد\nأهه تقريبا كان حاجة زي كده\nفرسول الله ﷺ سأل الملكين عن المنظر إللي شافه ده، فقال له الملكان: انطلق انطلق\nوكل ده ورسول الله ﷺ بيمشي معاهم من غير ما يعترض، ولا يصمم إنه يعرف الأول قبل ما يمشي، وده من حُسن خلقه ﷺ\nفمشي رسول الله ﷺ مع الملكين لحد ما وصلوا لرَوْضة مُعْتِمَة فيها من كل لون ربيع،\n\"فانْطَلَقْنا، فأتَيْنا علَى رَوْضَةٍ مُعْتَمَّةٍ، فيها مِن كُلِّ لَوْنِ الرَّبِيعِ\"\nيعني وصلوا عند بستان عظيم شديد الخضرة، ومن شدة الخُضرة يكاد يكون لونه أسود،\nوالبستان ده فيه من كل زهر الربيع، ونبات الربيع، يعني البستان ده من أجمل ما يكون\nولقى في وسط الروضة دي رجل طويل جدا لدرجة إنه مكنش شايف رأسه،\n\"وإذا بيْنَ ظَهْرَيِ الرَّوْضَةِ رَجُلٌ طَوِيلٌ، لا أكادُ أرَى رَأْسَهُ طُولًا في السَّماءِ\"\nوالرجل ده حوله أطفال كثير جدا،\n\"وإذا حَوْلَ الرَّجُلِ مِن أكْثَرِ وِلْدانٍ رَأَيْتُهُمْ قَطُّ\"\nفسأل رسول الله ﷺ الملكين: \nما هذا، ما هؤلاء؟!!\nفقال الملكان: انطلق انطلق\nفانطلقوا لحد ما وصلوا لحد ما وصلوا لروضة عظيمة جدا لم ير رسول الله ﷺ أحسن منها ولا أعظم،\n\"فانْطَلَقْنا فانْتَهَيْنا إلى رَوْضَةٍ عَظِيمَةٍ، لَمْ أرَ رَوْضَةً قَطُّ أعْظَمَ مِنْها ولا أحْسَنَ\"\nفقال له الملكان: ارقَ فيها، يعني اصعد فيها، فصعدوا كلهم لحد ما وصلوا لمدينة مبنية من طوبة فضة وطوبة ذهب،\n\"قالَ: قالا لِي: ارْقَ فيها،\nقالَ: فارْتَقَيْنا فيها، فانْتَهَيْنا إلى مَدِينَةٍ مَبْنِيَّةٍ بلَبِنِ ذَهَبٍ ولَبِنِ فِضَّةٍ\"\nفلما وصلوا لباب المدينة خبّطوا على الباب عشان حارس باب المدينة يفتح لهم، \n\"فأتَيْنا بابَ المَدِينَةِ فاسْتَفْتَحْنا فَفُتِحَ لنا فَدَخَلْناها\"\nففُتح لهم الباب، ودخلوا المدينة، فأول ما دخلوا قابلوا ناس نص وشهم جميل جدا كأجمل ما يرى الإنسان،\nونص وشهم الثاني قبيح جدا كأقبح ما يرى الإنسان،\n\"فَتَلَقَّانا فيها رِجالٌ شَطْرٌ مِن خَلْقِهِمْ كَأَحْسَنِ ما أنْتَ راءٍ، وشَطْرٌ كَأَقْبَحِ ما أنْتَ راءٍ\"\nفالملكين قالوا للناس دي روحوا انزلوا النهر إللي هناك ده،\nفنظر رسول الله ﷺ فشاف في نهر بيجري بالعرض ولون ماؤه أبيض شديد البياض،\n\"قالَ: قالا لهمْ: اذْهَبُوا فَقَعُوا في ذلكَ النَّهَرِ قالَ: وإذا نَهَرٌ مُعْتَرِضٌ يَجْرِي كَأنَّ ماءَهُ المَحْضُ في البَياضِ\"\nفذهب الناس ونزلوا في النهر ده وخرجوا ورجعوا لرسول الله ﷺ والملكين، \nفشاف رسول الله ﷺ وجوههم بقت في أحسن الصورة والشكل القبيح إللي كان فيهم مبقاش موجود،\n\"فَذَهَبُوا فَوَقَعُوا فِيهِ، ثُمَّ رَجَعُوا إلَيْنا قدْ ذَهَبَ ذلكَ السُّوءُ عنْهمْ، فَصارُوا في أحْسَنِ صُورَةٍ\" \nفقال الملكان لرسول الله ﷺ:\nهذه جنة عدن، وذاك منزلك\nيعني المكان إللي احنا فيه ده هو جنة عدن، وانت بيتك إللي هناك ده، \nفرفع رسول الله ﷺ بصره باتجاه المكان إللي الملكين شاوروا عليه فشاف قصر عامل زي السحابة البيضأء المنفردة المجتمع بعضها فوق بعض،\n\"فَسَما بَصَرِي صُعُدًا فإذا قَصْرٌ مِثْلُ الرَّبابَةِ البَيْضاءِ\"\nفلما رآه رسول الله ﷺ قال له الملكان: ذاك منزلك!!\nفقال لهما رسول الله ﷺ:\nبارك الله فيكما، سيبوني أدخله!\n\"قالَ: قُلتُ لهما: بارَكَ اللَّهُ فِيكُما ذَرانِي فأدْخُلَهُ\"\nفقالا له: دلوقتي لأ، لكن انت هتدخله بعدين\n\"قالَا: أمَّا الآنَ فلا، وأَنْتَ دَاخِلَهُ\"\nفقال لهما رسول الله ﷺ: \nأنا الليلة دي شوفت العجب، إيه الحاجات إللي أنا شوفتها دي؟!!\n\"قالَ: قُلتُ لهمَا: فإنِّي قدْ رَأَيْتُ مُنْذُ اللَّيْلَةِ عَجَبًا، فَما هذا الذي رَأَيْتُ؟\"\nفبدأ الملكان يشرحوا لرسول الله ﷺ الحاجات إللي شافها دي إيه،\n\"قالَ: قالَا لِي: أَمَا إنَّا سَنُخْبِرُكَ\"\nقالا لرسول الله ﷺ:\n◇الرجل الأول إللي كان بينزل الحجر على رأسه، فده إللي\n《 يأخذ القرآن فيَرفضه، وينام عن الصلاة المكتوبة》\nيعني إللي يترك حفظ القرآن والعمل بيه، وإللي ينام متعمد ويضيع صلاة من صلوات الفرائض،\nيعني يبقى واحد راجع من الشغل الظهر وتعبان ويقول لمراته  متصحنيش لصلاة العصر، ويصحى على المغرب مثلا أو يصحى العشاء،\nأو مياخدش بأي سبب من الأسباب يساعده إنه يصحى لصلاة العصر،\nأو واحد مثلا يظبط المنبه على ميعاد شغله ويضيع صلاة الصبح في ميعادها،\nفأي حد يتعمد إنه ينام عن صلاة من الصلوات الخمس أو يترك العمل بالقرآن 《ومات من غير ما يتوب》 هيبقى ده عقابه وعذابه في القبر إما إلى قيام الساعة، أو لحد ما يكفر عن ذنبه وميبقاش له باقي، \nولو مكنش له ذنوب تانية متبش منها يتحاسب عليها، ربنا يبدّل له قبره لروضة من رياض الجنة،\nلكن طول ما هو عنده ذنوب فهو هيتعذب بها في القبر، ربنا يعافينا وإياكم\nوطبعا الحكمة في إن العذاب ينزل على الرأس لأن النوم مكانه في الرأس فكانت العقوبة في مكان الإثم،\nوإللي بياخد بالأسباب عشان يصحى للصلاة لكن يغلب عليه النوم لأي سبب من الأسباب، ده مش داخل معانا في الكلام\n◇أما الرجل الثاني إللي بيُشرشر فمه إلى قفاه، وأنفه إلى قفاه وعينه إلى قفاه فهو:\n《فإنَّه الرَّجُلُ يَغْدُو مِن بَيْتِهِ، فَيَكْذِبُ الكَذْبَةَ تَبْلُغُ الآفَاقَ》\nيعني واحد يكذب كذبة وده ينقلها عنه وده ينقل عن ده، لحد ما كذبته تنتشر في الأرض،\nوطبعا في عصر الإنترنت ومواقع التواصل، بقى انتشار الكذبة الواحدة لكل الدنيا من أسهل ما يكون\nواحد يفتري على شخص ما وينشر الكذب ده والناس تنقله، تخيلوا كذبته دي هتنتشر أد إيه،\nعشان كده يا جماعة لازم ناخد بالنا من كلامنا بصفة عامة ومننشرش أي منشورات ولا نقول أي كلام إلا لما نكون متأكدين من الكلام إللي بنقوله، وطبعا نبعد عن النكت كمان إللي فيها كذب\nفكان العذاب في الفم لأن هو موضع الكذب، \nومن أشد أنواع الكذب ومن كبائر الذنوب :الكذب في المنام، يعني واحد يقول أنا شوفت رؤيا كذا وكذا، وهو مشفش حاجة وبيكذب،\nعشان كده بيتقطع من عند عينه،\nوحتى لو واحد قال إنه شاف رؤيا وحشة لفلان مثلا عشان يخوّفه ويخليه يتعظ ونيته كويسة، برده مينفعش ولا يجوز،\nلأن الغاية لا تبرر الوسيلة،\nمش عشان أنا نيتي كويسة وعايزة أعمل خير يبقى أعصي ربنا وارتكب المحرم\n☆ممكن حد يسأل ويقول:\nليه يعني الكذب في المنام أشد من الكذب في الحقيقة، مع إن إللي بيكذب في المنام هيضر نفسه بس، لكن الكذب في الحقيقة هيضر البشر إللي حواليه\nإجابة السؤال ده هنعرفه المرة الجاية إن شاء الله مع تفسير باقي الرؤيا، لأن جزء النهاردة مش هيكفي معلش\nطبعا مفيش مانع إنكم تفكروا في الإجابة وتستنتجوها وتكتبوها في تعليق"}, {"n": 172, "l": "الجزء 146 | احداث السنه السابعه من الهجرة | تفسير رؤيا رسول الله عن أهل البرزخ", "u": "https://www.facebook.com/groups/710210019782034/permalink/836523427150692/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#تفسير_رؤيا_رسول_الله_عن_أهل_البرزخ\nاتكلمنا المرة إللي فاتت عن الرؤيا إللي رآها رسول الله ﷺ وعرفنا تفسير أول حاجتين رسول الله ﷺ شافهم في الرؤيا ووقفنا عند سؤال مهم وهو:\nليه الكذب في المنام أشد من الكذب في الحقيقة، مع إن إللي بيكذب في المنام وإنه رأى رؤيا وهو مشفش حاجة يبقى كده هيضر نفسه بس، \nلكن الكذب في الحقيقة يعني الكذب على البشر هيضر إللي حواليه وممكن يأخذ حق مش له ومشاكل كتير بسبب الكذب ده\nالإجابة بكل بساطة هي إن الكذب في الرؤيا هي كذب على الله، والكذب على الله أشد من الكذب على المخلوقين، ربنا بيقول:\n\"وَمَنْ أَظْلَمُ مِمَّنِ افْتَرَىٰ عَلَى اللَّهِ كَذِبًا ۚ أُولَٰئِكَ يُعْرَضُونَ عَلَىٰ رَبِّهِمْ وَيَقُولُ الْأَشْهَادُ هَٰؤُلَاءِ الَّذِينَ كَذَبُوا عَلَىٰ رَبِّهِمْ ۚ أَلَا لَعْنَةُ اللَّهِ عَلَى الظَّالِمِينَ \"\nطيب ليه الكذب في الرؤيا يبقى كذب على ربنا\nلأن رسول الله ﷺ قال :\n\"الرُّؤْيَا الصَّالِحَةُ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنْ النُّبُوَّةِ\"\nوالنبوة لا تكون إلا وحياً من الله\nفاللي بيقول إنه شاف رؤيا وهو مشفهاش، فهو كده بيكذب على ربنا إنه أراه في المنام شيء محصلش أصلا وهو مشفش حاجة،\nيعني كأنه بيدعي إن ربنا أوحى له بشيء وده محصلش\nفكان الكذب على الله أشد وأَوْلى بعظيم العقوبة من إللي بيكذب على البشر، وبيسبب لهم أضرار أو يعطيهم حق مش لهم\n◇طيب وإللي عمل كده فعلا يعمل إيه\nيجب عليه إنه يتوب ويستغفر\nوطبعا يعمل الصالحات، لأن الحسنات بتمحي السيئات، ومش لازم يقول للي كذب عليه في الرؤيا إن كذب وإنه كان غلطان والكلام ده، يخليها بينه وبين نفسه وميكررهاش تاني\nنرجع بقى لتفسير باقي رؤيا رسول الله ﷺ\nالملكين أخبروا رسول الله ﷺ عن أول رجلين خلاص، وبيكملوا لرسول الله ﷺ تفسير باقي الأحداث وقالوا له:\nأما بقى الرجال والنساء العراة إللي كانوا في التنور أو الفرن فهم: \n《الزُّناة والزَّواني》\n\"وأَمَّا الرِّجَالُ والنِّسَاءُ العُرَاةُ الَّذِينَ في مِثْلِ بنَاءِ التَّنُّورِ، فإنَّهُمُ الزُّنَاةُ والزَّوَانِي\"\nيعني الرجال والنساء إللي بيقعوا في فاحشة الزنا والعياذ بالله،\nفعقوبة الزناة إن ربنا بيجمعهم في فرن من نار يتعذبوا فيه إلى يوم القيامة، وعذاب الآخرة أشد، \nطبعا العذاب ده إذا ما تابوش قبل ما يموتوا، لكن لو تابوا توبة نصوح وحالهم بعد التوبة أفضل من حالهم قبل التوبة، يبقى خلاص كده ربنا يغفر لهم ويبدل لهم سيئاتهم حسنات، ربنا بيقول:\n\"وَالَّذِينَ لَا يَدْعُونَ مَعَ اللَّهِ إِلَٰهًا آخَرَ وَلَا يَقْتُلُونَ النَّفْسَ الَّتِي حَرَّمَ اللَّهُ إِلَّا بِالْحَقِّ وَلَا يَزْنُونَ ۚ وَمَن يَفْعَلْ ذَٰلِكَ يَلْقَ أَثَامًا ۩ \nيُضَاعَفْ لَهُ الْعَذَابُ يَوْمَ الْقِيَامَةِ وَيَخْلُدْ فِيهِ مُهَانًا \"\nيعني إللي هيعمل كده ويموت هيتعذب عذاب شديد جدا؛\nإلا إللي يتوب قبل ما يموت،\n\"إِلَّا مَن تَابَ وَآمَنَ وَعَمِلَ عَمَلًا صَالِحًا فَأُولَٰئِكَ يُبَدِّلُ اللَّهُ سَيِّئَاتِهِمْ حَسَنَاتٍ ۗ وَكَانَ اللَّهُ غَفُورًا رَّحِيمًا\"\nفكل إللي احنا بنتكلم فيه ده عن ناس بتعمل المحرمات دي وماتت من غير توبة، لكن إللي بيتوب في الدنيا بصدق ربنا يقبل توبته وميدخلش في العذاب ده\nربنا يعافينا وإياكم ويعصمنا من الزَّلل\n◇أما الرجل إللي كان بيسبَح في نهر الدم ويترمى في فمه حجر، فهو: 《آكل الربا》\n\"وأَمَّا الرَّجُلُ الذي أتَيْتَ عليه يَسْبَحُ في النَّهَرِ ويُلْقَمُ الحَجَرَ، فإنَّه آكِلُ الرِّبَا\"\nفالرجل بيسبح في نهر الدم وكل ما ييجي ناحية الشاطيء بيفتح فمه غصب عنه ويترمى في فمه الحجر، \nفهو حتى لو  مش عايز يفتح فمه هيفتحه يعني هيفتحه مفيش نقاش\nفيفضل يسبح والصخور في بطنه في نهر الدم وهو متألم، ويرجع تاني وياخد صخور في فمه وهكذا، وكل ما ازداد أكله للربا في الدنيا زادت الصخور، \nويكون ده عذابه المستمر بحسب الربا إللي أكله\n☆طيب سريعا كده خلونا نعرف إيه هو الربا ده ،عشان في ممكن ناس متكنش عارفة\nالربا معناه الزيادة في شيء معين، يعني مثلا واحد يسلف واحد فلوس ألف جنيه مثلا، ويقول له لما تيجي ترجعهم لي ترجعهم ألف وخمسمائة،\nفهو هنا أخد زيادة على الفلوس وهي مش من حقه،\nوصورة تانية للربا وهي إن الرجل يسلف واحد ألف جنيه مثلا وبعدين يتفق مع الرجل إللي أخذ الفلوس على ميعاد معين،\nفلو جاء الميعاد ومدفعش يقول له خلاص، هنأجل بس هتدفع بعدين ألف وخمسين،\nولو جاء الميعاد إللي بعد كده ومدفعش، يقول له هنأجل ويبقى بعد كده ألف ومائة وهكذا،\nوبالتالي يا جماعة أي قرض ناخده أو حتى نعطيه لأي حد سواء أشخاص أو بنوك لازم يكون القرض إللي هناخده أو نعطيه يساوي القيمة إللي هنسددها أو هناخدها،\nيعني أخدنا ألف نرجعها ألف، أخدنا مائة نرجعها مائة، أعطينا ألف يبقى ناخدهم ألف، \nأي زيادة ندفعها عن المبلغ إللي أخدناه أو أعطيناه حتى لو جنيه واحد يبقى حرام\nوطبعا بيع الذهب بالذهب محرم برده؛ لأنه من الربا إلا لو كان نفس الوزن بالضبط مفيش فيه زيادة أو نقصان ومش هتدفع أي فلوس زيادة،\nيعني مثلا لو واحدة عايزة تبيع خاتم وتشتري واحد جديد،\nفتقوم رايحة للبيّاع وتديله الخاتم وتاخد واحد بداله جديد وتدفع الفرق، الصورة دي لا تجوز وهي من الربا المحرم\nطيب الصح إيه\nالصح إن المرأة تبيع الخاتم مثلا وتاخد تمنه في إيدها، وبعدين تشوف الخاتم إللي هي عايزاه وتمنه كم، وتجهز تمنه وبعدين تعطيه للبائع أو زي ما قلنا تبيع ذهب بذهب من غير ما تدفع أو تاخد أي فلوس، يعني جرامات قصاد جرامات، وبكده يبقى هي خرجت من الربا المحرم\n♧طبعا موضوع الربا ده متفرع وفي مسائل وكلام كتير عن سبب التحريم وأثاره السلبية، وغيره،\nوده مش موضوعنا، أنا بس بديكم معلومات أساسية عشان لما تسمعوا أو تقرأوا الكلمة تكونوا فاهمين معناها،\nلأن زي ما قلتلكم قبل كده الهدف من السيرة النبوية مش بس نعرف قصة حياة رسول الله ﷺ وحياة الصحابة، لكن كمان عشان نتعرّف ونتعلم أساسيات الإسلام \nنرجع للملكين وشرحهم لرسول الله ﷺ، قالوا:\n◇الرجل إللي انت شوفته ده وكان شكله وحش جدا فهو:\n《مالك خازن النار》\n\"وأَمَّا الرَّجُلُ الكَرِيهُ المَرْآةِ، الذي عِنْدَ النَّارِ يَحُشُّهَا ويَسْعَى حَوْلَهَا، فإنَّه مَالِكٌ خَازِنُ جَهَنَّمَ\"\nوهو شكله وحش كده لأنه بيعذب أهل النار بمنظره، عذاب نفسي يعني، لأن المنظر المفزع مرعب، \nوالرعب في حد ذاته عذاب، فيجتمع على أهل النار العذاب الجسدي والعذاب النفسي،\nوربنا قال عن خزنة النار ، يعني حراسها والمسؤولين عن تعذيب أهل النار وهم أعوان مالك خازن النار:\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا قُوا أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا النَّاسُ وَالْحِجَارَةُ 《عَلَيْهَا مَلَائِكَةٌ غِلَاظٌ شِدَادٌ لَّا يَعْصُونَ اللَّهَ مَا أَمَرَهُمْ وَيَفْعَلُونَ مَا يُؤْمَرُونَ》 \"\n☆كل إللي احنا شوفنا عذابهم دول هم من أهل الكبائر، يعني إللي كانوا بيعملوا كبائر الذنوب مش معاصي عادية وماتوا من غير ما يتوبوا منها،\nوممكن الواحد فيهم يجمع أكثر من عذاب، يعني واحد ممكن يكون ينام عن الصلاة المكتوبة وفي نفس الوقت بياكل الربا وفي نفس الوقت بيكذب وفي نفس الوقت زاني\nويموت قبل ما يتوب من كل ده، فيتعذب بقى كل العذاب إللي احنا اتكلمنا عنه ده لحد ما يخلص الكبائر بتاعته دي،\nوالحياة إللي بيكونوا عايشينها دي اسمها حياة البَرْزَخ،\nوالبَرْزَخ هو الفترة الزمنية إللي بتكون بين موت الإنسان لحد ما يُبعث يوم القيامة، فاللي يموت على الإسلام والطاعة بيُنعّم في القبر،\nوإللي يموت على الكفر والمعصية بيُعذب، زي ما شوفنا من أصحاب الكبائر دول\n☆طيب الناس أصحاب الكبائر دي وإللي ماتوا من غير ما يتوبوا منها، هل هم مُخلدين في النار، يعني مش هيطلعوا منها أبدا\nأصحاب الكبائر زي الزنا والسرقة وقتل النفس بغير حق والكذب وغيرها من الكبائر غير مخلدين في النار،\nيتعذبوا في القبر وفي النار على قدر ذنوبهم ويطلعوا ماداموا 《مش مُسْتحِلين》\nيعني ما دام الواحد فيهم مش شايف إن الكذب حلال فعلى الأساس ده بيكذب، أو السرقة حلال أو قتل المسلمين حلال، يبقى هو مش هيكون مُخلّد في النار للأبد، هيتعذب فيها بقدر ذنوبه ويخرج،\n¤وهنا في ملحوظة مهمة\nوهي إن الخلود نوعين: \n◇خلود معناه الأبد وإنه مش هيطلع من النار أبداااا، زي خلود الكفار والمشركين في النار، ربنا بيقول:\n\"كَذَٰلِكَ يُرِيهِمُ اللَّهُ أَعْمَالَهُمْ حَسَرَاتٍ عَلَيْهِمْ ۖ وَمَا هُم بِخَارِجِينَ مِنَ النَّارِ\"\n◇والنوع التاني من الخلود هو الإقامة الطويلة، يعني إن الواحد يقعد فترة طويلة جدا في مكان معين، والعرب كانت تقول عن الإقامة الطويلة خلود، واحنا عارفين إن القرآن نزل بلغة العرب،\nفلما ربنا يقول: \n\"وَمَن يَقْتُلْ مُؤْمِنًا مُّتَعَمِّدًا فَجَزَاؤُهُ جَهَنَّمُ خَالِدًا فِيهَا وَغَضِبَ اللَّهُ عَلَيْهِ وَلَعَنَهُ وَأَعَدَّ لَهُ عَذَابًا عَظِيمًا \"\nفالآية هنا مش معناها إنه هيفضل في النار للأبد ومش هيخرج منها أبدا زيه زي الكافر،\nلكن معناه إنه هيقعد في النار فترة طويلة يتعذب فيها عشان يكفر عن إللي عمله،\nوطبعا زي ما قلنا إذا لم يستحل المعصية، يعني مكنشي بيشوف إن إللي عمله ده حلال،\nفأول ما الواحد يستحل المعصية ومات على كده يبقى  خلاص كفر ويكون خالد مُخلد في النار ميخرجش منها أبدا\n☆طيب هل الكلام ده نهائي، يعني أي حد هيموت على كبيرة من الكبائر من غير ما يتوب منها يبقى أكيد هيتعذب، ولّا ممكن ربنا يتجاوز عنه\nشوفوا، \nإخلاف الوَعِيد من مكارم الأخلاق عند البشر، فما بالكم برب العالمين وأرحم الرحمين،\nيعني مثلا لو مدير شركة قال للموظفين بتوعه كلكم هتاخدوا خصم عشان غلطتم في كذا وكذا وكذا،\nفبعدين المدير ده عفا عنهم لأي سبب من الأسباب، ومخصمش منهم حاجة، محدش من العمال هيقول للمدير انت ليه معقبتناش زي ما قلت، بالعكس ده هيبقوا مُمتنّين ومبسوطين من المدير إنه معقبهمش\nولله المثل الأعلى في السماوات والأرض، ربنا قال إن إللي هيعمل كذا هيكون عقابه كذا، \nفلما العباد وقعوا في إللي ربنا نهى عنه، وبعدين ربنا خلف وعيده ورحمهم لحكمة يعلمها سبحانه، فدي صفة من صفات الكمال لله عز وجل\nفأصحاب الكبائر إللي يموتوا من غير توبة دول أمرهم إلى الله، إذا شاء عذبهم وإذا شاء غفر لهم وعفا عنهم،\nهو الحكيم سبحانه هو يرى ويعلم مين إللي يستحق العذاب ومين إللي يستحق العفو، وربنا بيقول:\n\"إِنَّ اللَّهَ لَا يَغْفِرُ أَن يُشْرَكَ بِهِ وَيَغْفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَاءُ\"\nفاللي هيستحق العذاب من أهل الكبائر زي الزناة مثلا وربنا لم يعفو عنه، هيتعذب بالعذاب إللي احنا قلنا عليه ده،\nولو لسه له باقي عذاب هيدخل النار يتعذب لحد ما يخلص ذنوبه وبعدين ربنا يخرجه منها بفضله ورحمته\nفاحنا يا جماعة حتى لو شوفنا واحد مات وهو بيعمل أي كبيرة من الكبائر منقدرش نجزم ونأَكد إن ده هيدخل جنة ولّا نار،\nلكن نقول أمرهُ إلى الله إذا شاء عذبه وإذا شاء غفر له،\nلكن لاشك طبعا إن إللي يموت على كبيرة من الكبائر، ده سوء خاتمة وعلى حسب النصوص الشرعية والأدلة فهو كده هيتعذب،\nلكن منقدرش نجزم بكده، يعني منقدرش نقول فلان ده مات على سوء خاتمة فهو هيتعذب أكيد وهو من أهل النار ، لأ، دي مش بتاعتنا، دي بإيد ربنا \nفاحنا ناخد العظة والعبرة عشان نهايتنا متبقاش زيه وخلاص\nخلونا بقى نطلع من جو العذاب والآلام دي وندخل الروضة أو البستان ونشوف مين الرجل إللي كان قاعد فيها ده\nقال الملكان:\nأما الرجل الطويل إللي كان قاعد في البستان فهو:\n《إبراهيم، وأما الولدان الذين حوله فكل مولود مات على الفطرة 》\n\"وأَمَّا الرَّجُلُ الطَّوِيلُ الذي في الرَّوْضَةِ فإنَّه إبْرَاهِيمُ صَلَّى اللهُ عليه وسلَّمَ، وأَمَّا الوِلْدَانُ الَّذِينَ حَوْلَهُ فَكُلُّ مَوْلُودٍ مَاتَ علَى الفِطْرَةِ\"\nيعني إبراهيم عليه السلام قاعد في الروضة الجميلة دي وحوله كل الأطفال إللي ماتوا وهم صغيرين على الفطرة قبل سن البلوغ،\nفأبناء المسلمين إللي بيموتوا وهم صغيرين قبل البلوغ 《بصفة عامة》 في كفالة إبراهيم وسارة، بيراعوهم لحد ما ييجي يوم القيامة فيرجعوهم لآبائهم وأمهاتهم،\nوبقول بصفة عامة لإننا مينفعش نشهد لشخص مُعين بجنة أو نار حتى لو كان طفل\nفدي بشارة لكل أب وأم مات له حد من أطفاله وهو صغير، يعني تخيل كده ابنك كان يفضل معاك ولّا يكون في رعاية إبراهيم عليه السلام أبو الأنبياء وزوجته سارة \n أكيد طبعا في كفالة إبراهيم ورعايتهم أفضل من رعاية أبوه وأمه،\nعلى الأقل إبراهيم عليه السلام وزوجته سارة مش هيضربوه ولا يشتموه ولا يصرخوا في وشه، زي ما بنشوف ونسمع عن إللي الأباء والأمهات بيعملوه في عيالهم بحجة إنهم بيربوهم\nطبعا موت الأطفال الصغار ده مؤلم جدا للآباء والأمهات، عشان كده ربنا بيجازي إللي بيصبر على الابتلاء الشديد ده إن ربنا يأمر الملائكة إنها تَبني للأب أو الأم بيت في الجنة يسموه بيت الحمد، يدخلوه يوم القيامة\n☆طيب وأطفال المشركين \nده سؤال سأله واحد من الصحابة لرسول الله ﷺ، هل أطفال المشركين داخلين مع أطفال المسلمين ولّا إيه حالهم،\n\"فَقالَ بَعْضُ المُسْلِمِينَ: يا رَسولَ اللَّهِ، وأَوْلَادُ المُشْرِكِينَ؟\"\nرسول الله ﷺ قال للصحابي إللي سأل : وأطفال المشركين معاهم\nلكن يا جماعة في وقت الرؤيا دي مكنش لسه ربنا أوحى لرسول الله ﷺ إن أطفال المشركين لهم وضع خاص وإنهم لهم امتحان في الآخرة، هيمتحنوا، زي ما شرحنا قبل كده بالتفصيل في الجزء الخامس والتسعين،\nفهو قال للصحابة إللي كان يعرفه في الوقت ده، وبعدين ربنا أوحى له إن أطفال المشركين لهم امتحان في الآخرة، زي أهل الفترة والمجنون، وهو ده أرجح الأقوال،\nوالدليل على الكلام ده حديث رسول الله ﷺ:\n\"يُؤتى بأربعة يوم القيامة: \nبالمولود وبالمعتوه وبِمَن مات في الفترة وبالشيخ الفاني كلهم يتكلم بحُجته،\nفيقول الرب تبارك وتعالى لعُنقٍ من النار: أُبْرُز!\nفيقول لهم إني كنت أبعث إلى عبادي رسلا من أنفسهم وإني رسول نفسي إليكم ادخلوا هذه،\nفيقول من كُتب عليه الشقاء يا رب أين ندخلها ومنها كنا نفر، قال: ومن كتب عليه السعادة يمضي فيقتحم فيها مسرعا، قال: فيقول الله تبارك وتعالى أنتم لرسلي أشد تكذيباً ومعصية فيدخل هؤلاء الجنة وهؤلاء النار\"\nطبعا أنا مش هعيد الشرح تاني بقى، احنا اتكلمنا عنه قبل كده، فممكن ترجعوا للجزء الخامس والتسعين لو حابين تراجعوا الشرح بالتفصيل \n◇المدينة بقى إللي رسول الله ﷺ صعد لها وكانت مبنية من طوبة من الفضة وطوبة من الذهب فدي كانت الجنة، والناس إللي قابلهم وكان نص وشهم جميل ونص وشهم قبيح دول ناس: \n《 خلطوا عملاً صالحًا، وآخر سيئًا تجاوز الله عنهم 》\n\"وأَمَّا القَوْمُ الَّذِينَ كَانُوا شَطْرٌ منهمْ حَسَنًا وشَطْرٌ قَبِيحًا، فإنَّهُمْ قَوْمٌ خَلَطُوا عَمَلًا صَالِحًا وآخَرَ سَيِّئًا، تَجَاوَزَ اللَّهُ عنْهمْ\"\nعارفين لما نخلط اللبن بالمية\nأهه نفس التشبيه تقريبا، العمل الصالح مخلوط مع العمل السيء ومش عارفين نفصلهم عن بعض زي اللبن والمية كده نحسهم حاجة واحدة،\nعشان كده كان نص وجههم قبيح والنص التاني حسن، فدول ربنا عفا عنهم، \nوعشان يتخلصوا من النص السيء ده الملكين قالوا لهم إنهم يروحوا ينزلوا في نهر كان معترض الجنة، يعني كان بعرض الجنة والنهر ده كان لونه أبيض زي اللبن،\nويحتمل إن الماء إللي في النهر ده هو المقصود في دعاء رسول الله ﷺ:\n\" اغسل خطاياي 《بالماء》 والثلج والبَرَد\"\nفالماء إللي في النهر ده ماء مُنظف ومُنقّي ومُطهر، فلما نزلوا فيه أزال السوء إللي كانوا فيه، وبقى وجههم كله حسن.\nوقال الملكان لرسول الله ﷺ إن المكان إللي هم فيه ده هو جنة عدن، وشاوروا لرسول الله ﷺ على قصر عالي بعيد قالوا له إن ده بيته، وكان شكله جميل عامل زي السحابة البيضاء المتراكب بعضها على بعض،\nفرسول الله ﷺ كان عايز يدخل البيت ده ويشوفه شكله إيه من الداخل، فالملكان قالوا له إنه مش هينفع يدخله دلوقتي لأن لسه عمره في الدنيا مانتهاش، لما ينتهي هيدخله أكيد\nوفي النهاية الملكين أخبروا رسول الله ﷺ عن نفسهم وإنهم جبريل وميكائيل، لأن رسول الله ﷺ كل ده مكنش يعرف إنهم ملكين أصلا لأنهم لما جاءوا لرسول الله ﷺ في بداية الرؤيا كانوا على هيئة رجلين ميعرفهمش رسول الله ﷺ.\nوبكده انتهت رؤيا رسول الله ﷺ وتفسيرها\nالمرة الجاية إن شاء الله هندخل مع رسول الله ﷺ في بيته ونشوف بعض المواقف بينه وبين زوجاته وإزاي كان بيتصرف معاهم"}, {"n": 173, "l": "الجزء 147 | احداث السنه السابعه من الهجرة | طريقة تعامل رسول الله صلى الله عليه وسلم مع اخطاء زوجاته | الجزء الأول", "u": "https://www.facebook.com/groups/710210019782034/permalink/836523530484015/", "t": "لما نعدي من قدام القبر قولو الدعاء دا زي ما سيدنا محمد قال هتلاقو تحت \n#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وأربعون\n#أحداث_السنة_السابعة_من_الهجرة\n#طريقة_تعامل_رسول_الله_مع_أخطاء_زوجاته\n#الجزء_الأول\nاتكلمنا في الأجزاء الأخيرة إللي فاتت عن غزوات وسرايا لرسول الله ﷺ، وبعدين اتكلمنا عن رؤيا رسول الله ﷺ شافها في المنام وحكاها للصحابة،\nهنسيب كل الأحداث دي وندخل مع رسول الله ﷺ في بيته ونشوف بعض مواقف له مع زوجاته أمهات المؤمنين وإزاي كان بيتعامل معهن، وخصوصا لما يحصل منهن خطأ\n◇الموقف الأول:\nبما إننا بقى لسه خارجين من غزوة خيبر ورسول الله ﷺ تزوج بنت زعيم اليهود السابق حُيَي بن أخطب السيدة صفية رضي الله عنها، خلونا نشوف الموقف إللي حصل بينها وبين بعض زوجات رسول الله ﷺ \nدخل رسول الله ﷺ على صفية رضي الله عنها فلقاها بتبكي، وكانت رضي الله عنها من النوع إللي بيبكي كتير، عارفين لما نقول على حد دمعته قريبة\nأهه صفية رضي الله عنها كانت كده،\nالمهم، \nرسول الله ﷺ سألها بتبكي ليه، فقالت له إن حفصة بتقول عليها إنها بنت يهودي، وحفصة بنت عمر رضي الله عنهما هي زوجة رسول الله ﷺ،\nفرسول الله ﷺ قال لصفية قولي لها:\nمحمد زوجي وأبي هارون وعمي موسى\nيعني إيه المشكلة لما تكوني بنت يهودي، أبوكِ هارون وعمك موسى، وهو كليم الله وفوق كل ده زوجك محمد ﷺ خاتم الأنبياء والمرسلين،\nوصفية رضي الله عنها كانت من سُلالة هارون عليه السلام، \nففرحت صفية رضي الله عنها بالمكانة العظيمة دي، لأن مفيش حد زيها، أبوها نبي، وعمها نبي وزوجها نبي\nفرسول الله ﷺ تعامل مع الموقف بكل حكمة وخفف الألم النفسي عن صفية رضي الله عنها،\nطيب وحفصة رضي الله عنها، رسول الله ﷺ عمل معاها إيه\nرسول الله ﷺ لما شافها بعد الموقف ده قال لها :\n\"اتقِ الله يا حفصة\"\nيعني مش معنى إنك بتغيري يبقى ده يديكي الحق إنك تسخري أو تعايري إللي بتغيري منه، وربنا بيقول :\n\"يَا أَيُّهَا الَّذِينَ آمَنُوا لَا يَسْخَرْ قَوْمٌ مِّن قَوْمٍ عَسَىٰ أَن يَكُونُوا خَيْرًا مِّنْهُمْ وَلَا نِسَاءٌ مِّن نِّسَاءٍ عَسَىٰ أَن يَكُنَّ خَيْرًا مِّنْهُنَّ\"\nرسول الله ﷺ أه راضى صفية خلاص لكنه كان لازم يعلم السيدة حفصة إن إللي عملته ده كان غلط\nوزوجات رسول الله ﷺ مش معصومات من الخطأ، فوارد جدا إنهم يقعوا في الخطأ لأنهن من البشر،\nواحنا بقى مينفعش نحتج بأفعال زوجات رسول الله ﷺ الخاطئة ونبرر لنفسنا ونقول عادي ما زوجات رسول الله ﷺ  وقعوا في الخطأ ده\nأيوة وقعوا في الخطأ لكن رسول الله ﷺ صحح الخطأ بتاعهم، \nمش إنه سابهم على الخطأ من غير ما يعلمهم، وخدوا بالكم رسول الله ﷺ اتعامل مع الموقف إزاي،\nهو فقط قال لها : اتقِ الله، هو ذكّرها بالله لأنه عارف إن حفصة رضي الله عنها صوامة قوامة بشهادة رب العالمين،\nورسول الله ﷺ لم يُعايرها ويقولها انتِ إزاي صوامة قوامة وتعملي الغلط ده، زي ما ناس كتير بتعمل وللأسف بيكون غرضها الشماتة\nلكن رسول الله ﷺ المُرَبّي بيعلمنا إننا نعالج الغلط صح، مش  نعالج الغلط بغلط زيه\nوبما إننا اتكلمنا عن حفصة وإنها صوامة قوامة بشهادة رب العالمين، خلونا نعرف إيه القصة ورا الموضوع ده وهو الموقف التاني معانا النهاردة\n◇ حصل خلاف بين رسول الله ﷺ وبين حفصة رضي الله عنها فطلقها رسول الله ﷺ \nأصلا كسر المرأة طلاقها، فما بالكم لما إللي يطلق هو رسول الله ﷺ\nأكيد الموضوع صعب جدا على السيدة حفصة،\nطبعا مفيش حديث واضح يقول لنا إيه سبب الطلاق ده، لكن العلماء استنبطوا السبب من الآية:\n\"إِذْ أَسَرَّ النَّبِيُّ إِلَىٰ بَعْضِ أَزْوَاجِهِ حَدِيثًا فَلَمَّا نَبَّأَتْ بِهِ وَأَظْهَرَهُ اللَّهُ عَلَيْهِ عَرَّفَ بَعْضَهُ وَأَعْرَضَ عَن بَعْضٍ ۖ فَلَمَّا نَبَّأَهَا بِهِ قَالَتْ مَنْ أَنبَأَكَ هَٰذَا ۖ قَالَ نَبَّأَنِيَ الْعَلِيمُ الْخَبِيرُ \"\nقالوا إن الزوجة هنا هي حفصة، وإن رسول الله ﷺ قال لها سر، لكنها أفشت سر رسول الله ﷺ،\nفلما عرف رسول الله ﷺ إن حفصة أفشت السر عن طريق الوحي، رسول الله ﷺ طلقها\nفلما طلقها قعدت تبكي ودخل عليها خالاها الإثنين يواسوها《إخوة أمها》 وهي كانت تبكي وتقول:\nوالله ما طلقني من شِبَع...يعني هو مطلقنيش عشان زهق مني\nفوهم عالحال ده لقوا الباب بيخبط، فقام أخوالها بفتح الباب فلقوا رسول الله ﷺ،\nفاستغربوا من مجيئه ﷺ، يعني إيه إللي خلاك تيجي يا رسول الله مش انت خلاص طلقتها..فقال لهم رسول الله ﷺ وحفصة تسمع:\nجاءني جبريل وقال إن الله جل جلاله أرسلني من فوق العرش وقال : قل لمحمد راجع حفصة، يعني رجع حفصة لعصمتك تاني؛ فإنها صوّامة قوّامة\nيعني بتصوم كتير وتصلي قيام الليل كتير،\nشايفين إزاي إن مفيش تعارض بين إن المرأة تكون صوّامة قوّامة وتقع في الخطأ، سواء كان إفشاء سر أو غيره\nلكن مش معنى الكلام إننا نتساهل في الوقوع في الغلط\nالشاهد من الكلام إن مهما كان الإنسان تقيّا ومُطيع لله فمش بعيد عليه إنه يغلط، ولما يغلط مفيش مشكلة إنه يصلح الغلط ويتوب ويستغفر، لأن التوبة بتمسح الذنب\n خلونا بقى نشوف موقفين لحبيبة رسول الله ﷺ عائشة رضي الله عنها، ونشوف تعامل رسول الله ﷺ معاها كان عامل إزاي\n◇الموقف الثالث:\nفي مرة جاء أبو بكر الصديق رضي الله عنه لرسول الله ﷺ، فكان بيستأذن للدخول على رسول الله ﷺ فسمع السيدة عائشة وهي رافعة صوتها على رسول الله ﷺ، فأَذِن رسول الله ﷺ لأبي بكر في الدخول،\nفلما دخل راح ناحية عائشة، وقال لها:\n\" يَا ابْنَةَ أُمِّ رُومَانَ وَتَنَاوَلَهَا، أَتَرْفَعِينَ صَوْتَكِ عَلَى رَسُولِ اللهِ ﷺ\"\nيعني انتِ إزاي ترفعي صوتك على رسول الله ﷺ، وهو رسول الله وانتِ متجيش حاجة جنبه، وداخل عليها عايز يضربها،\nفرسول الله ﷺ حال بينه وبينها، يعني حاشه عنها ووقف بينه وبينها عشان ميضربهاش\n☆وطبعا موقف السيدة عائشة هنا وإنها تعلي صوتها على رسول الله ﷺ موقف مذموم، والدليل على كده إن أبو بكر الصديق غضب منها،\nفاحنا مينفعش نستشهد بالموقف ده في تحسين التصرف المذموم وهو الغضب ورفع الصوت، ونقول ما السيدة عائشة كانت بترفع صوتها على رسول الله ﷺ\nلكن نتعلم منه إزاي نعالج التصرف المذموم ده صح\n♡شوفوا رد فعل رسول الله ﷺ كان إيه\nبعد ما خرج أبو بكر رضي الله عنه من عند رسول الله ﷺ، قعد رسول الله ﷺ يترضى السيدة عائشة، عشان يُهدّأ من غضبها، وقال لها:\nشوفتي أنا دافعت عنك إزاي ومنعته من إنه يؤذيكِ\n\"أَلَا تَرَيْنَ أَنِّي قَدْ حُلْتُ بَيْنَ الرَّجُلِ وَبَيْنَكِ\"\nفهنا رسول الله ﷺ تعامل بكل حكمة، ومردش عليها في غضبها لكنه هدّاها، ومقلهاش مثلا انتِ إزاي تعلي صوتك عليّ وأنا رسول الله،\nوالناس سامعة صوتك من برة البيت، وأنا شكلي إيه قصاد الناس و...و.... \nأيوة السيدة عائشة أخطأت، لكن الحكيم إللي يعالج الخطأ صح مش يزوّد الخطأ،\nلو رسول الله ﷺ كان قالها مثلا الكلام إللي قلناه ده، كان هيبقى إيه رد فعل السيدة عائشة\nغضبها كان هيزيد أكيد وكان ممكن تقع في معصية أكبر ويحصل ما لا يُحمد عقباه\nفنستفيد من موقف رسول الله ﷺ ده إزاي نتعامل مع الشخص الغضبان صح بحيث إنه غضبه ميزدش ويقع في خطأ أكبر، وإن من حقوق المعاشرة تحمّل الغضب،\nيعني كل طرف يتحمل غضب الطرف التاني في وقت غضبه، ويتجاوز عن زلّاته إللي ممكن تحصل بسبب الغضب ده،\nزي موقف السيدة عائشة في رفع صوتها على رسول الله ﷺ،\nوبكرر مرة تانية يا جماعة مينفعش الاستشهاد بالحديث على تحسِين التصرف المذموم\nفبسبب تصرف رسول الله ﷺ الحكيم ده الموقف عدى بسلام، وبعد كم يوم جاء أبو بكر مرة تانية لرسول الله ﷺ فاستأذن للدخول عليه، فلما دخل شافه بيضحك مع السيدة عائشة،\nفقال له أبو بكر:\n\"يَا رَسُولَ اللهِ أَشْرِكَانِي فِي سِلْمِكُمَا، كَمَا أَشْرَكْتُمَانِي فِي حَرْبِكُمَا \"\nيعني يا رسول الله شاركوني في إللي مخليكم مبسوطين كده، زي ما شاركتوني المشكلة إللي حصلت بينكم\nوبكل بساطة انتهت المشكلة\n☆ملحوظة:\nالقصة إللي أنا قلتها دي\n هي القصة الصحيحة؛ لأن في قصة تانية مشابهة لها لكنها مُنكرة لا تصح عن السيدة عائشة ولا عن رسول الله ﷺ ولا عن أبي بكر،\nالقصة المنكرة دي بتقول:\n《 إن حصل خلاف بين رسول الله ﷺ وبين السيدة عائشة، فسألها رسول الله ﷺ تحبي تحكّمي مين بيننا؟ تحبي تحكمي عمر، فقالت له لأ، ده عمر شديد وغليظ،\nفقال لها تحكمي أباكِ فوافقت، فجاء أبو بكر فقال لها رسول الله ﷺ تتكلمي انتِ ولّا اتكلم أنا، قالت له اتكلم انت ولا تقل إلا حقا، \nفهنا غضب أبو بكر وراح ضربها على وجهها، وبسبب الضربة أنفها نزفت دم، فهربت السيدة عائشة واستخبّت خلف ظهر رسول الله ﷺ، وقال رسول الله ﷺ لأبي بكر مش ده إللي احنا عايزينه منك،\nفخرج أبو بكر وهو غضبان، والسيدة عائشة قامت من جنب رسول الله ﷺ وهي لسه زعلانة،\nفرسول الله ﷺ قال لها قربي مني، فمرضيتش، فقال لها رسول الله ﷺ انتِ مش كنتِ لسه بتستخبي ورايا دلوقتي، واصطلحوا》\nدي القصة باختصار، وزي ما قلت هي قصة منكرة، لا تصح عن رسول الله ﷺ \n◇الموقف الرابع:\nالقصة الثانية للسيدة عائشة رضي الله عنها وهي إللي بتحكيها بتقول:\nلما كان رسول الله ﷺ في ليلتي التي هي لي، يعني كانت الليلة دي ليلتها إللي بيبات فيها عندها،\nجاء وفتح الباب رويداً رويداً يعني فتح الباب بهدوووء، وبعدين خلع نعله عشان النعل ميعملش صوت وهو لابسه وبيتحرك بيه، ومَشَى بهدوء، وبعدين وضع النعل جنبه على الفراش بهدوء برده،\nكل ده وهو مفكّر إن السيدة عائشة نايمة، فبيتحرك بهدوء كده عشان ميصحيهاش،\nوهي كانت صاحية ومراقبة إللي بيحصل كله\nرسول الله ﷺ يادوب مفيش ثواني وضع جنبه على الفراش وراح قايم تاني، وأخذ نعله وفتح الباب ومشي، وكل ده رويداً رويداً، يعني كل حركة كان بيعملها بمنتهى الهدوء عشان ميصحيش السيدة عائشة،\nطبعا لو واحدة فينا حصل معاها الموقف ده هتعمل إيييه\nبالضبط كده، وهو ده إللي السيدة عائشة رضي الله عنها عملته\nقامت لبست حجابها وخرجت وراء رسول الله ﷺ، وهي كانت مفكرة إنه هيروح لبعض نسائه في ليلتها،\nالسيدة عائشة بتوصف بقى هي عملت إيه بتقول:\n\"فقمت وراءه وتقنّعت إِزاري حتى وجدتُّه عند البقيع\" \nيعني لبست نقابها وخرجت وراء رسول الله ﷺ وفضلت ماشية وراه لحد ما وصل للبَقيع، والبقيع هي مقابر أهل المدينة،\nطبعا الدنيا ضلمة ومفيش عواميد نور ولا أي حاجة خالص\nفشافته السيدة عائشة وهو بيرفع يده ثلاث مرات بالدعاء وينزلها\nوبعدين استدار رسول الله ﷺ عشان يرجع لبيته، فلما شافته السيدة عائشة راجع، استدارت هي كمان عشان ترجع للبيت،\nفأسرع رسول الله ﷺ في المشي، فأسرعت هي كمان،\nفهَرْوَل رسول الله ﷺ فهرولت السيدة عائشة، والهرولة هو المشي السريع، وهو بين الجري وبين المشي،\nوبعدين مشي رسول الله ﷺ بتمهل، براحة يعني، فمشيت السيدة عائشة براحة هي كمان وسبقته ووصلت البيت قبله،\nأول ما دخلت الغرفة راحت نازلة تحت اللحاف\nلكن انتم عارفين إللي بيمشي بسرعة وكان لسه بيجري أنفاسه هتكون سريعة، مش أنفاس واحد نايم خالص\nفدخل رسول الله ﷺ البيت فشاف اللحاف طالع نازل مع أنفاس السيدة عائشة،\nفسأل رسول الله ﷺ السيدة عائشة:\nمالك يا عائشة ! حَشْيَا رَابِيَة؟\nيعني عندي مشكلة في صدرك، في حاجة بتوجعك، لأنه ﷺ كان لسه سايبها نايمة عادي ورجع لقاها بتنهج، يبقى أكيد في حاجة\nفالسيدة عائشة قالت له: لا شيء، مفيش حاجة يعني،\nفقال لها رسول الله ﷺ:\nأخبريني أو ليُخبِرني اللطيف الخبير\nيعني أنا كده كده هعرف من الوحي، فانتِ قوليلي أحسن\nفقالت عائشة: يا رسول الله! مهما يكتم الناس يعلمه الله!نعم!\nيعني هي بتُقر حقيقة وبتقول إن مهما هنخبي أي حاجة ربنا هيعلمها أكيد\nوحكت السيدة عائشة لرسول الله ﷺ إللي حصل كله، وإنها كانت صاحية لما جاء وكانت مراقبة الموقف كله وبعدين خرجت وراه ورجعت، لحد ما هو جاء وسألها،\nفرسول الله ﷺ سألها:\nأنتِ السواد الذي كان أمامي؟\nيعني انتِ الشخص إللي كان ماشي قصادي، ويُستدل برده من الجملة دي إن السيدة عائشة كانت لابسة حجاب لونه أسود\nفقالت له السيدة عائشة: نعم!\nفهنا غضب رسول الله ﷺ وكان لا يغضب إلا أن تُنتَهك حرمات الله، يعني بيغضب فقط لما حد يتعدى حدود الله، ومكنش بيغضب ولا بينتقم لنفسه لنفسه أبدا\nوسبب غضبه هنا إن السيدة عائشة ظنت إنه تركها وراح لزوجة تانية من زوجاته وكده ظلم،\nومينفعش هي تظن فيه كده؛ لأنه أعدل الناس، ولو هو لم يعدل مين إللي هيعدل\nفرسول الله ﷺ غضب ولَهَدَها فِي صَدْرها لَهْدَةً أَوْجَعَتْها، يعني رسول الله ﷺ ضربها أو دفعها في صدرها دفعة أوجعتها، وقال :\n\"أَظَنَنْتِ أَنْ يَحِيفَ اللهُ عَلَيْكِ وَرَسُولُهُ\"\nيعني فكرتي إني هظلمك أو ربنا هيظلمك بأن يكون الدور عليكِ وأسيبك وأروح لغيرك\nوبدأ رسول الله ﷺ يشرح للسيدة عائشة إيه إللي حصل بالضبط.\n☆ثواني كده\nهو رسول الله ﷺ الرحيم الحكيم صاحب الخلق العظيم ضرب السيدة عائشة\nشوفوا،\nالسيدة عائشة قالت:\n\" فَلَهَدَنِي فِي صَدْرِي لَهْدَةً أَوْجَعَتْنِي\"\nواللهد في اللغة معناه:\nالدفع في الصدر أو اللّكز أو الضغط أو الغَمْز، يعني لا يرقى إنه يكون في منزلة الضرب إللي احنا عارفينه ده وبيكون غرضه التحقير والوجع الزيادة ،\nفالوجع إللي السيدة عائشة حست بيه كان وجع بسيط  المقصود منه التنبيه لحاجة مهمة جدا مينفعش تنساها أو متخدش بالها منها؛ \nوهي إنها مهما كانت غيرتها على رسول الله ﷺ ومحبتها له فمينفعش أبدا إنها تظن إن رسول الله ﷺ ممكن يظلم امرأة عشان امرأة اخرى من نسائه\nفالموقف ده أصلا دليل على كمال خلق النبي ﷺ ورحمته ، ورقة قلبه ﷺ، \nفهو عاتب السيدة عائشة عتاب لطيف عشان يعلم السيدة عائشة ويعلمنا إن ربنا عز وجل ورسوله ﷺ لا يظلمان أحد، وإنه لا يجوز لأي حد إنه يسيء الظن بالله ورسوله، \nبل الواجب إحسان الظن بالله، والرضا بما قسمه عز وجل \nولو رسول الله ﷺ يا جماعة كان غرضه الضرب والإهانة فعلا مكنش اكتفى بخبطة أو غمزة بسيطة في الصدر كده،\nلكن كان هيفرغ قوته في جوانب جسم السيدة عائشة أو وجهها\nوالدليل كمان إن الضربة دي كانت مجرد ضربة خفيفة وإن والهدف منها التنبيه والتعليم هو الحوار إللي حصل بعدها، الحوار بينهم كان هادي جدا وكان بيشرح لها الموقف بكل هدوء وحتى السيدة عائشة نفسها كانت متجاوبة مع رسول الله ﷺ، وقعدت تتكلم معاه ومعيطتش مثلا وخصوصا إنها كانت صغيرة في السن، \nخلونا كده نشوف الحوار إللي حصل بينهم:\nبدأ رسول الله ﷺ يشرح لها النص التاني من القصة إللي هي متعرفوش، وهو إنه لما نام على الفراش لمدة ثواني وبعدين قام،\nالسبب إللي خلاه يقوم هو كما يقول ﷺ:\n\"فإنَّ جِبْرِيلَ أَتَانِي حِينَ رَأَيْتِ، فَنَادَانِي، فأخْفَاهُ مِنْكِ، فأجَبْتُهُ، فأخْفَيْتُهُ مِنْكِ، وَلَمْ يَكُنْ يَدْخُلُ عَلَيْكِ وَقَدْ وَضَعْتِ ثِيَابَكِ، وَظَنَنْتُ أَنْ قدْ رَقَدْتِ\"\nيعني جبريل جاء لرسول الله ﷺ وناداه بصوت واطي لم تسمعه السيدة عائشة، عشان متصحاش، وجبريل عليه السلام مدخلش البيت لأن السيدة عائشة كانت متخففة من ملابسها كعادة النائم،\nورسول الله ﷺ كان مفكر إنها نايمة، ومرضاش يصحيها عشان متخافش إنها لوحدها بالليل، بحكم إنها صغيرة في السن يعني،\n\"فَكَرِهْتُ أَنْ أُوقِظَكِ ، وَخَشِيتُ أَنْ تَسْتَوْحِشِي\"\nفخرج رسول الله ﷺ لجبريل، فقال له جبريل:\n\"إِنَّ رَبَّكَ يَأْمُرُكَ أَنْ تَأْتِيَ أَهْلَ الْبَقِيعِ فَتَسْتَغْفِرَ لَهُمْ  \"\nفهنا بقى السيدة عائشة بكل ذكاء غيّرت الموضوع، وقالت لرسول الله ﷺ:\nكيفَ أَقُولُ لهمْ يا رَسولَ اللهِ؟ \nيعني لو أنا عديت على المقابر أقول لهم إيه،\nفقالَ قُولِي:\n\"السَّلَامُ علَى أَهْلِ الدِّيَارِ مِنَ المُؤْمِنِينَ وَالْمُسْلِمِينَ، وَيَرْحَمُ اللَّهُ المُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ، وإنَّا إنْ شَاءَ اللَّهُ بكُمْ لَلَاحِقُونَ\"\nوده الدعاء إللي بيقال لو حد دخل المقابر أو عدى من جنب المقابر\nوبكده المشكلة اتحلت بكل بساطة، الغرض مش الانتقام أو الانتصار للنفس، سواء من السيدة عائشة أو من رسول الله ﷺ، هدف كل واحد الوصول للحق، عشان كده الموقف اتحل بسهولة\nلكن طول ما الهدف هو الانتصار للنفس وإني مطلعش أنا الغلطان حتى لو حساب الطرف التاني يبقى مشاكلنا عمرها ما هتتحل\nمحتاجين نتعلم من خلق رسول الله ﷺ في التعامل مع الخطأ، وطبعا الكلام للجميع للرجال والنساء،\n\"لَّقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا\"\nطبعا في مواقف تانية لرسول الله ﷺ كتير مع زوجاته، وإزاي كان بيتعامل مع أخطائهن، على حسب كل موقف،\nبس زي مانتم شايفين الجزء بتاع النهاردة خلص\nفلعل وعسى نبقى نتكلم بعدين عن المواقف دي،\nوإن شاء الله المرة الجاية إما هنرجع للسرايا ونكمل الأحداث الخارجية،\nأو هنتكلم عن بعض قصص الحديث النبوي إللي رسول الله ﷺ كان بيحكيها للصحابة، لسه محددتش بصراحة"}]);
